(window.STORIES=window.STORIES||[]).push(...[{"n": 208, "l": "الجزء 182 | احداث السنه الثامنه من الهجرة | ولادة ابراهيم بن رسول الله", "u": "", "t": "#قصص_الأنبياء(٢)\n#السيرة_النبوية\n#الحلقة_مائة_واثنان_وثمانون\n#أحداث_السنة_الثامنة_من_الهجرة\n#ولادة_إبراهيم_بن_رسول_الله\nوقفنا المرة إللي فاتت عند الثلاث سرايا إللي أخرجهم رسول الله ﷺ بعد فتح مكة في المناطق المحيطة بمنطقة مكة،\n◇السرية الأولى:\nكانت بقيادة خالد بن الوليد رضي الله عنه، والسرية دي كانت في شهر شوال، بعد ما هدم خالد بن الوليد صنم العزى وحكينا قصة هدم الصنم في الجزء المائة وسبعة وستون،\nالسرية دي كانت لبني جُذَيْمة، وكانوا في بلدة أسفل مكة ناحية يَلَمْلَم،\nوكان الهدف من السرية دي هو الدعوة إلى الإسلام،\nفاتجه خالد بن الوليد لبني جذيمة ومعاه حوالي أربعمائة صحابي،\nفلما وصلت السرية لبني جذيمة دعاهم خالد للإسلام زي ما رسول الله ﷺ أمره،\nفقالوا لخالد:\n《صَبَأْنَا صَبَأْنَا》\nوكلمة صبأنا دي لها ماضي سيء مع المسلمين، فهي كلمة مشهورة بين المشركين ومعناها عندهم اتباع دين محمد ﷺ،\nيعني إللي يتبع دين الإسلام يبقى صَبَأ، فانتشرت الكلمة وبقت معروفة عندهم وبقت عادة،\nوكانت قريش بتقولها بقصد ذم والسخرية من المسلمين الأوائل في مكة، وخالد كان عارف كده، \nفبني جُذَيمة أسلموا، فبدل ما يقولوا أسلمنا قالوا صَبَأْنَا، \nفخالد فكرهم إنهم بيستهزأوا\nفبسبب سوء التفاهم ده وعدم التثبت من مقصدهم بدأ خالد يقتل منهم ويأسر، وكل واحد من الصحابة إللي كانوا معاه أخذ الأسير إللي أسره،\nوبعد كم يوم أمر خالد الصحابة إن كل واحد منهم يقتل أسيره\nفعبد الله بن عمر بن الخطاب رضي الله عنه قال:\n\" وَاللَّهِ لاَ أَقْتُلُ أَسِيرِي ، وَلاَ يَقْتُلُ رَجُلٌ مِنْ أَصْحَابِي أَسِيرَهُ\"\nيعني لا أنا ولا حد من أصحابي هيقتل أسيره ورفضوا أوامر خالد بن الوليد،\nفلما رجعوا لرسول الله ﷺ حكوا له إللي حصل فرفع رسول الله ﷺ يده وقال:\n \"اللَّهُمَّ إِنِّي أَبْرَأُ إِلَيْكَ مِمَّا صَنَعَ خَالِدٌ، اللَّهُمَّ إِنِّي أَبْرَأُ إِلَيْكَ مِمَّا صَنَعَ خَالِدٌ\" قالها مرتين،\nيعني يارب أنا مش موافق على إللي خالد عمله ده، \nفرسول الله ﷺ أعلن تبرؤه من إللي حصل ده أمام الناس؛ عشان الكل يستوعب ويفهم خطورة الخطأ إللي حصل ده،\nو مكانة خالد ممنعتش رسول الله ﷺ إنه يَجهر بتبرأه من إللي عمله خالد؛\nلأن التستر على الأخطاء إللي زي كده هيشجع على تكرارها وممكن يساعد على بقائها وازديادها بعدين،\nفكان غَضَب رسول الله ﷺ من خالد لأنه استعجل ولم يتثبت ويفهم منهم يقصدوا إيه بالضبط بكلمة صبأنا دي؛\n لأن الصّبَأْ معناه الخروج من دين، فيُقال عن الرجل صابئ إذا خرج من دين كان فيه إلى دين تاني،\nفقولهم: صبأنا، كلام يَحتمل أن يكون معناه خرجنا من ديننا إلى دين الإسلام أو دين آخر غير الإسلام ، من يهودية أو غيرهم من الأديان،\nفلما خالد ملقاش منهم كلام صريح يوضح دخولهم في الإسلام قاتلهم وأسرهم،\nوإللي حصل ده مكنش معصية متعمدة من خالد بن الوليد رضي الله عنه، لكنه كان اجتهاد خاطئ منه،\nعشان كده رسول الله ﷺ لم يعاقبه على خطأه ده،\nولم يعزله مثلا عن قيادة الجيش بعد كده، بالعكس ده كان بيقدمه ويجعله قائد على الجيوش،\nوخصوصا إن خالد لم يتعمد مخالفة أوامر رسول الله ﷺ  بإنه قَاتَل أو قتل مسلمين ورسول الله ﷺ مكنش أمره بالقتال،\nلكن خطأه هنا كان زي خطأ أسامة بن زيد رضي الله عنه لما قتل رجل بعد ما قال لا إله إلا الله خوفا من السيف، واحنا كنا حكينا قصته في الجزء مائة وثلاثة وأربعون،\nفكل ده يوضح لنا نقطة مهمة وهي عدم عصمة الصحابة رضي الله عنهم\nهمّ أه لهم مكانتهم ولهم فضلهم إللي محدش هيقدر يوصله، لكنهم غير معصومين من الخطأ، \nبيجتهدوا ويُصيبوا وساعات يجتهدوا ويخطئوا زي ما حصل مع خالد رضي الله عنه\n◇السرية الثانية:\nكانت سرية بقيادة الطُّفَيل بن عمرو الدّوْسي سيد قبيلة دوس إللي اتكلمنا عنه في الجزء السابع والعشرين،\nكانت السرية دي في شهر شوال من السنة الثامنة من الهجرة بعد فتح مكة، \nوكان سبب السرية هو تطهير الجزيرة العربية من الأصنام،\nفلما رسول الله ﷺ قرر إنه يتجه للطائف بعث الطفيل بن عمرو إلى صنم اسمه ذِي الْكَفَّيْنِ، وهو واحد من أصنام الآلهة العربية في قبيلة دوس، \nوالصنم ده كان من الخشب، و كان لواحد اسمه عَمْرِو بْنِ حُمَمَةَ الدَّوْسِيِّ وهو كبير دَوس وأحد حكماء العرب المُعمّرِين، والناس كانت بتجيله من بعيد عشان يستشيروه في أمورهم،\nفأمر رسول الله ﷺ الطفيل إنه يستعين بقومه دَوْس لهدم الصنم ده، فخرج الطفيل بسرعة واتجه لقومه فهدم ذَا الْكَفَّيْنِ وحرقه، \nوأخذ الطفيل أربعمائة من قومه واتجهوا لرسول الله ﷺ في الطائف، وكان رسول الله ﷺ وصل الطائف قبل مجيء الطفيل بأربعة أيام.\n◇السرية الثالثة:\nسرية قيس بن سعد بن عبادة إلى قبيلة صُدَاء ناحية اليمن:\nلما انصرف رسول الله ﷺ من وادي الجعرانة جهّز رسول الله ﷺ أربعمائة فارس وجعل عليهم قيس بن سعد بن عبادة وأمره إنه يتجه إلى قبيلة صُدَاء عشان يقاتلهم،\nفجاء لرسول الله ﷺ واحد اسمه زِيَاد بن الحارث الصُّدائي فسأل عن السرية إللي خرجت دي، فعرف إنها متجهة لقومه،\nفقال لرسول الله ﷺ:\n\"يا رسول الله أنا وَافِدهم إليك فارْدُد الجيش وأنا أتكفل بإسلام قومي وطاعتهم\"\nيعني بيقول لرسول الله ﷺ إنه من قبيلة صداء وإنه هيتكفل بدعوة قومه وإنه يأتي بهم مسلمين، فطلب من رسول الله ﷺ إنه يرجّع السرية دي وميخليهاش تقاتل قومه،\nفقال له رسول الله ﷺ:\n\"اذهب إليهم فرُدّهم\"\nيعني روح لهم وقولهم يرجعوا، فقال لرسول الله ﷺ:\n\"إن راحلتي قد كَلّت\"\nيعني البعير إللي أنا جاي عليه تعب من السفر الطويل ومش هيقدر يتحرك، فبعث لهم رسول الله ﷺ واحد يأمرهم بالرجوع،\nفرجعت السرية فعلا ورجع الصدائي لقومه فجاءوا المدينة بعد خمسة عشر يوما فأسلموا، \nوقيل: إن الصدائي كتب إليهم برسالة يدعوهم فيها للإسلام فجاء وفدهم بعد خمسة عشر يوما يعلن إسلامهم فقال رسول الله للصدائي: \n\"إنك مُطاع في قومك يا أخا صداء\"\nيعني قومك سمعوا كلامك وجاءوا مسلمين زي مانت قلت لهم من غير مشاكل ومن غير اعتراضات، \nفقال الصدائي لرسول الله ﷺ: بل الله هداهم\nوبكده يبقى خلصنا السرايا إللي حصلت في السنة الثامنة من الهجرة،\nكل الأحداث إللي هتيجي بقى في أواخر السنة الثامنة من الهجرة إما أحداث داخلية اجتماعية أو أحداث خارجية فيها دعوة للإسلام ولكن من غير قتال\nمن الأحداث الخارجية إللي حصلت ومرتبطة بالدعوة:\nإرسال رسول الله ﷺ لعمرو بن العاص برسالة إلى سيدا عُمَان جيفر و عبد أو عبّاد ابنا الجُلَنْدِي يدعوهم فيها للإسلام،\nوكانت عُمَان دولة مشركة في الوقت ده،\nقال رسول الله ﷺ في الرسالة:\n\"بِسْمِ اللّهِ الرّحْمَنِ الرّحِيمِ مِنْ مُحَمّدِ بْنِ عَبْدِ اللّهِ إلَى جَيْفَرَ وَعَبْدٍ ابْنَيْ الْجُلَنْدَي سَلَامٌ عَلَى مَنْ اتّبَعَ الْهُدَى، أَمّا بَعْدُ؛\nفَإِنّي أَدْعُوكُمَا بِدِعَايَةِ الْإِسْلَامِ،\nأَسْلِمَا تَسْلَمَا فَإِنّي رَسُولُ اللّهِ إلَى النّاسِ كَافّةً، لِأُنْذِرَ مَنْ كَانَ حَيّاً وَيَحِقّ الْقَوْلُ عَلَى الْكَافِرِينَ،\nفَإِنّكُمَا إنْ أَقْرَرْتُمَا بِالْإِسْلَامِ وَلّيْتُكُمَا، \nوَإِنْ أَبَيْتُمَا أَنْ تُقِرّا بِالْإِسْلَامِ فَإِنّ مُلْكَكُمَا زَائِلٌ عَنْكُمَا، وَخَيْلِي تَحُلّ بِسَاحَتِكُمَا وَتَظْهَرُ نُبُوّتِي عَلَى مُلْكِكُمَا\"\nخلونا نحلل رسالة رسول الله ﷺ كده:\n◇أولا:\nرسول الله ﷺ لمّا ذكَرهم بأسمائهم مجردين كده، ده \nلأنهم لا يملكون الإرادة السياسية في القرار،\nيعني همّ مش ملوك حقيقيين، ولا همّ سادة على قومهم، ولكنهم بينفذوا أوامر أسيادهم وهم المجوس في فارس،\nفرسول الله ﷺ لما بَعث رسالة لهرقل قال: إلى هرقل عظيم الروم؛ لأنه فعلا مَلك والناس بتخضع له،\nلكنه هنا كلّم جيفر وعبد أو عبّاد باسمهم مجرد لأنهم مجرد عمال لا يملكون من أمر السيادة شيء\n◇ثانيا:\nرسول الله ﷺ قالهم إنهم يفضلوا في مناصبهم في حالة دخولهم للإسلام، والعرض ده هيساعدهم ويشجعهم إنهم يدخلوا الإسلام؛ \nلأنه ﷺ عارف إن موضوع الملك ده يهمهم،\nيعني يا جماعة زي كده إللي حصل في توزيع غنائم حنين،\nرسول الله ﷺ أعطى بعض الناس عشان يتألف قلوبهم،\nوهنا وعد جيفر وعبد إنهم هيفضلوا في الحكم لو دخلوا في الإسلام\n◇ثالثا:\nرسول الله ﷺ بيذكرهم إن نبوة ودين محمد ﷺ هيبلغ كل الأرض، يعني متتغروش بقوة الدولة إللي انتم تابعين لها دلوقتي،\nالدولة دي هتنتهي في يوم من الأيام وهتبقى تحت راية الإسلام وساعتها محدش هينفعهم ولا حد هيساعدهم ولا هيبقى لهم مكان\nده كان محتوى الرسالة، ورسول الله ﷺ اختار عمرو بن العاص بالذات لتوصيل الرسالة لأنه كان ذكي جدا، ده غير إن عمرو كان سفير قريش قبل الإسلام،\nفهو بيعرف يتعامل بذكاء مع الملوك، واحنا شوفنا تعامله مع النجاشي قبل كده،\nتوجه عمرو بن العاص لعُمان ودخل على عبد وكان هو الأخ الأصغر وكان أحلم وأسهل الرجلين،\nوبدأ يتحاور معاه ويقنعه بالإسلام وطلب منه إنه يدخّله على أخوه جيفر،\nوبعد حوار طويل مع جيفر وعبد وبحكمة وذكاء شديد من عمرو بن العاص رضي الله عنه استطاع إنه يقنع عباد وجيفر بالإسلام وفعلا أسلما، \nوأسلم شعبهما بالكامل، ودخلت دولة عُمان بكاملها في دولة المسلمين،\nواستمر جيفر وعبد في حكم عمان زي ما رسول الله ﷺ وعدهم\n☆ملحوظة:\nحديث عمرو بن العاص مع جيفر و عبد طويل جدا ومحتاج جزء لوحده في الشرح\nفاللي عنده فضول يقرأ الحوار هيلاقيه في التعليقات، والحديث موجود في كتاب زاد المعاد في هدي خير العباد لابن القيم\nمن الأحداث الداخلية إللي حصلت في المدينة إن السيدة مارية أنجبت طفل لرسول الله ﷺ،\nواحنا كنا قلنا قبل كده في الجزء مائة واثنان وثلاثون إن السيدة مارية أهداها المقوقس لرسول الله ﷺ في السنة السابعة من الهجرة، فأسلمت وأخذها رسول الله ﷺ ملك يمين ولم يتزوجها،\nفحملت السيدة مارية وأنجبت في ذي الحجة من السنة الثامنة من الهجرة ولدا يشبه رسول الله ﷺ، وسماه رسول الله ﷺ إبراهيم،\nوكان رسول الله ﷺ يحبه جدا وكان بيروح له مخصوص يشوفه، يعني مكنش بيطلب حد يجيبله الولد، لأ، كان هو بنفسه بيروح يشوفه\n☆عندنا هنا سؤال وتوضيح بخصوص السيدة مارية:\n◇السؤال :\nليه رسول الله ﷺ لم يتزوج من السيدة مارية وظلت عنده مِلك يمين\nلأن زواج الإماء ممنوع في الشرع إلا لِمن لا يستطيع التزوج بالحرة ويخشى على نفسه الوقوع في الحرام،\nيعني لا يجوز للحر إنه يتزوج الأَمة إلا بشرطين:\n◇الأول:\nعدم الطَّوْل، وهو ألا يستطيع نكاح حرة مسلمة.\n◇الثاني:\nخوف العَنَت، وهو خوف الوقوع في الحرام\nربنا بيقول:\n\"وَمَنْ لَمْ يَسْتَطِعْ مِنْكُمْ طَوْلًا أَنْ يَنْكِحَ الْمُحْصَنَاتِ الْمُؤْمِنَاتِ فَمِنْ مَا مَلَكَتْ أَيْمَانُكُمْ مِنْ فَتَيَاتِكُمُ الْمُؤْمِنَاتِ....... ذَلِكَ لِمَنْ خَشِيَ الْعَنَتَ مِنْكُمْ \"\nوالشرع شدّد في موضوع عدم الزواج من الإماء ده لِمَا يترتب عليه من استرقاق الولد، يعني الولد بيتّبع أمّه في الحرية، أو الرق،\nورسول الله ﷺ يقدر يتزوج من نساء حرائر زي ما هو عايز فمش محتاج إنه يتزوج أمة،\nوالموضوع مختلف بالنسبة للسيدة صفية بنت حُيَي والسيدة جُوَيرية بنت الحارث؛ فهن في الأصل كُنّ حرائر وبعدين أُخِذوا في السّبْي،\nفأعتقهن رسول الله ﷺ وتزوجهن إكراما لهن وكمان لمكانتهن ولتأليف قلوب قبائلهن، يعني هو لم يتزوجهن إلا بعد ما أعتقهن،\nأما السيدة مارية فهي من البداية جارية من القبط، فتسرّى بها رسول الله ﷺ كمِلك يمين من غير ما يتزوجها،\nوكان ممكن رسول الله ﷺ يُعتق مارية ويتزوجها هي كمان، لكن رسول الله ﷺ قدوة وأفعاله تشريع،\nفهو لما يتسرّى بالنساء فده بيؤكد إن الموضوع حلال،\nوالصحابة كان عندهم إماء يتسرّون بهن مع زوجاتهم\n◇والكلام ده هياخدنا لنقطة التوضيح\nو هي إن الأَمة إذا وَلَدت لسيدها بقت اسمها أم ولد، وطفلها إللي اتولد ده بيكون حر،\nوهي نفسها بتبقى حرة لكن بعد موت سيدها، يعني بعد ما سيدها يموت بقت زيها زي أي امرأة حرة، لا تُباع ولا تُشترى، وتقدر تتزوج زواج عادي،\nفالسيدة مارية بقت حرة لأنها ولدت لرسول الله ﷺ ولد، لكن حريتها دي تكون بعد موت رسول الله ﷺ،\nلكن حريتها دي مختلفة عن باقي النساء، يعني هي لا يجوز لها إنها تتزوج بعد رسول الله ﷺ؛ لأن زوجات رسول الله ﷺ اللاتي دخل بهن وإماءه لا يجوز لهن الزواج من بعده ﷺ،\nودي حاجة خاصة برسول الله ﷺ\nطبعا مصادر الكلام إللي قلته بالأدلة والشرح المُفَصّل هتلاقوها في التعليقات\nإن شاء الله المرة الجاية هنكمل باقي الأحداث إللي حصلت بعد ما رسول الله ﷺ رجع المدينة"}, {"n": 209, "l": "الجزء 183 | احداث السنه الثامنه من الهجرة | الإسلام والرق | منبر رسول الله وحنين الجذع", "u": "", "t": "#قصص_الأنبياء(٢)\n#السيرة_النبوية\n#الحلقة_مائة_وثلاثة_وثمانون\n#أحداث_السنة_الثامنة_من_الهجرة\n#الإسلام_والرّق\n#منبر_رسول_الله_وحنين_الجذع\nبدأنا المرة إللي فاتت الكلام عن الأحداث إللي حصلت في المدينة بعد رجوع رسول الله ﷺ،\nواتكلمنا عن ولادة إبراهيم بن رسول الله ﷺ من مارية القبطية، وساعتها مكنش عند رسول الله ﷺ أبناء غير فاطمة رضي الله عنها؛\nلأن زينب بنت رسول الله ﷺ ماتت في السنة الثامنة من الهجرة زي ما قلنا قبل كده في الجزء الثالث والستين،\nفكان رسول الله ﷺ سعيد جدا بولادة ابنه إبراهيم وكان يحبه حبا شديدا ﷺ \nقبل ما نكمل باقي الأحداث، في سؤال عن الجزء إللي فات بيقول:\nالإسلام حرر العبيد ومنع الرق وده يتنافى مع وجود السيدة مارية كجارية، فإزاي نجمع بين الاتنين\n◇أولا:\nالإسلام لم يمنع الرّق أو يُحرمه، ومفيش أي نص من القرآن ولا السنة بيقول بمنع الرق أو تحريمه،\nلكن الإسلام شجّع على عتق العبيد و رغّب فيه وفتح أبواب للعتق ده،\nزي مثلا إنه جعله كفارة للقتل الخطأ، وكفارة للجماع في نهار رمضان، وكمان في كفارة اليمين وغيرها\n◇ثانيا:\nقبل الإسلام كان في مصادر كتيرة للاسترقاق منها:\nالحروب، و المَدِين إذا عجز عن الدين يكون رقيقا،  والسطو والخطف، والفقر والحاجة،\nفالإسلام قضى على كل ده ما عدا رق الحروب، \nوهو إللي بيُفرَض على الأسرى من الكفار ويُفرَض على نسائهم وأولادهم،\nيعني لو في حرب بين مسلمين وكفار وانتصر المسلمون أخذ المسلمون من العدو رجال أو نساء كعبيد و إماء ودول اسمهم السّبْي،\nفمصادر الرق مع ظهور الإسلام كانت كثيرة، لكن طُرق ووسائل التحرر من الرق كانت تكاد تكون معدومة\nفالإسلام قلب الموازين دي كلها فأكثر من أسباب الحرية ، وسَدَّ مَسالك الاسترقاق ووضع وصايا تسد المسالك دي،\nيعني مثلا ربنا بيقول في حديث قدسي:\n\"ثَلَاثَةٌ أَنَا خَصْمُهُمْ يَوْمَ الْقِيَامَةِ ، وَمَنْ كُنْتُ خَصْمَهُ خَصَمْتُهُ ، وذكر منهم : رَجُلٌ بَاعَ حُرًّا فَأَكَلَ ثَمَنَهُ\"\nفبالوعيد ده اتقفل باب الخطف إللي كان سبب رئيسي في انتشار الرق\nواحنا شوفنا إن زيد بن حارثة كان حر واتخطف واتباع كعبد، لحد ما وصل لرسول الله ﷺ واتبناه في القصة إللي احنا قلناها قبل كده،\nوالإسلام موقفش عند كده وبس، ده حتى في الحروب أضاف خيارين مكنوش موجودين قبل كده وهما:\nالمَنّ والفداء،\nيعني قبل الإسلام كان الأسر في الحروب من أظهر مظاهر الاسترقاق، وكل حرب لابد فيها من أسرى، \nوكان العُرف المنتشر ساعتها إن الأسرى لا حرمة لهم ولا حق، وهم بين أمرين إما القتل وإما الرّق،\nلكن الإسلام فتح باب المَنّ وهو العفو عن الأسرى، أو الفداء يعني إن الأسير أو أهله يدفعوا فدية مقابل إطلاق سراح الأسير ده\nواحنا شوفنا إللي حصل في بدر للأسرى إللي رسول الله ﷺ أطلق سراحهم بالفداء،\nوشوفنا رسول الله ﷺ لما تزوج جويرية بنت الحارث وكانت أسيرة وبنت زعيم بني المصطلق،\nو ساعتها الصحابة أطلقوا سراح الأسرى إللي عندهم، والأسرى دول همّ عبيد وإماء، وكل ده بدون مقابل\nفمع وجود العبيد والإماء كجزء من المجتمع المسلم في عهد رسول الله ﷺ كان لازم يبقى في قواعد للتعامل معاهم ويكون في قدوة قصادهم تورّيهم إزاي يتعاملوا مع الإماء والعبيد دول،\nوالقدوة كان رسول الله ﷺ،\nفكان طبيعي إن يكون عنده إماء يتسرّى بهن زيه زي باقي الصحابة،\nفبالتالي مفيش مشكلة إن رسول الله ﷺ يخلى مارية عنده ملك يمين يتسرّى بها بدون ما يُعتقها ويتزوجها \nواحنا قلنا قبل كده إن رسول الله ﷺ كان عنده أربعة إماء:\nمارية القبطية وريحانة بنت زيد واتكلمنا عنها في الجزء المائة، \nوواحدة أصابها رسول الله ﷺ في بعض السبي والثانية أهدتها له زوجته زينب بنت جحش رضي الله عنها،\n◇كده الكلام هياخدنا لسؤال تاني مهم برده، وهو ليه الإسلام مقفلش باب الرق حتى في الحروب \nوالإجابة هي:\nإن الحرية حق أصيل للإنسان، ولا يُسلب الإنسان الحق ده إلا لِعارض أو سبب مُستجد،\nيعني الأسير الكافر المقاوم للحق والعدل هو: إما ظالم، أو مُعين على ظلم، أو أداة في تنفيذ أو إقرار الظلم ده،\nفحريته هنا كانت فرصة لانتشار الطغيان والاستعلاء على الآخرين، والوقوف في وجه الحق ، ومنعه من الوصول إلى الناس\nفالإسلام هنا ضيّق على إنسان استغلَّ حريته أسوأ استغلال، فإذا سقط أسيراً بسبب حرب عدوان انهزم فيها، فإمساكه بمعروف مدة أسره تصرف سليم ومن العدل\nومع كل ده فهو برده عنده فرص كتير لاستعادة حريته سواء بالكفارات أو بالمن والفداء زي ما قلنا من شوية\nومع كل إللي احنا قلناه ده، الإسلام كمان وضع قواعد تحفظ للأسير ده كرامته وحقوقه وتضمن حسن معاملته إللي مكنتش أصلا موجودة قبل كده\nيعني قبل الإسلام الأسرى أو العبيد مكنش لهم أي حقوق نهائي ولا بيتعاملوا معاملة البشر أصلا\nولو تفتكروا كان من اعتراض قريش على رسول الله ﷺ لما جاء برسالة الإسلام إنهم بيقولوا إن إزاي رسول الله ﷺ بيساوي بين العبد والحر، ومفيش بينهم فرق إلا بالتقوى، \nفالمساواة دي كانت حاجة كبيرة جدا عندهم، يعني من وجهة نظرهم إزاي محمد ﷺ يساوي بين أبو جهل مثلا وبين بلال رضي الله عنه، دي بالنسبة لهم كارثة\nفمع إباحة وجود أسرى أو بمعنى أصح عبيد وإماء في الإسلام فهم لهم فرصة في العتق ولهم حقوق محفوظة مكنتش موجودة قبل الإسلام\nومن الحقوق دي:\n◇أولا :\nضمان الغذاء والكساء مثل أوليائهم، قال رسول الله ﷺ عن العبيد:\n\"هُمْ إِخْوَانُكُمْ ، جَعَلَهُمْ اللَّهُ تَحْتَ أَيْدِيكُمْ ،فَمَنْ جَعَلَ اللَّهُ أَخَاهُ تَحْتَ يَدِهِ، فَلْيُطْعِمْهُ مِمَّا يَأْكُلُ،\nوَلْيُلْبِسْهُ مِمَّا يَلْبَسُ، وَلَا يُكَلِّفُهُ مِنْ الْعَمَلِ مَا يَغْلِبُهُ فَإِنْ كَلَّفَهُ مَا يَغْلِبُهُ فَلْيُعِنْهُ عَلَيْه\"\nيعني العبيد دول بشر زيكم وربنا خلّاكم انتم المتحكمين فيهم، فاللي عنده عبد من العبيد يأَكّله من إللي بياكل منه، مش هو ياكل أفضل الطعام والعبد إللي عنده يأكّله أكل سيء أو حتى أقل من إللي هو بياكله،\nوكذلك الملابس، مش عشان هو عبد يبقى يلبس ملابس رديئة وسيده يلبس أحسن الثياب،\nولو كلفتم العبيد بعمل ميكونش فوق طاقتهم، ولو العمل فوق طاقتهم يبقى تساعدوهم\n◇ثانيا:\nحفظ كرامة العبيد، قال رسول الله ﷺ:\n\" مَنْ قَذَفَ مَمْلُوكَهُ وَهُوَ بَرِيءٌ مِمَّا قَالَ جُلِدَ يَوْمَ الْقِيَامَةِ، إِلَّا أَنْ يَكُونَ كَمَا قَالَ\"\nيعني إللي يتهم مملوكه بحاجة هو معملهاش هيتجلد يوم القيامة بسبب اتهامه الظالم ده، ومش هينجيه من الجلد إلا إن العبد يكون فعلا زي ما سيده قال عنه\nولو السيد ضرب عبده أو تعدى عليه فكفارة إللي عمله ده إنه يعتقه، قال رسول الله ﷺ:\n\"مَن لَطَمَ مَمْلُوكَهُ، أَوْ ضَرَبَهُ، فَكَفَّارَتُهُ أَنْ يُعْتِقَهُ\"\n◇ثالثا:\nالعدل مع الرقيق والإحسان إليهم.\nيعني مثلا عبد الرحمن بن عوف كان بيمشي وسط العبيد بتوعه محدش يقدر يفرقه عنهم؛ لأنه لا يتقدمهم ولا يلبس إلا من لباسهم، يعني مش بيمشي قدام وهمّ ماشيين وراه،\nأو بيلبس لبس مميز عنهم،\nو مرة عمر بن الخطاب رضي الله عنه شاف عبيد واقفين مش بيأكلوا مع سادتهم، فغضب عمر وقال لمواليهم :\nما لقوم يَسْتأثرون على خُدّامِهم ؟ \nيعني انتم بتخصوا نفسكم بالأكل وسايبين العبيد بتوعكم واقفين مش بياكلوا معاكم؟\nفدعا عمر العبيد فأكلوا معهم، تخيلوا\nبقى يا جماعة في دين في الدنيا يأمر بحقوق للعبيد كده زي الإسلام؟ \nده دلوقتي أصلا في ناس أحرار حالهم أسوأ من العبيد وحتى مش بياخدوا حقوق العبيد إللي رسول الله ﷺ أمر بيها لهم\nطبعا أنا مش هتكلم عن مكانة العبيد عند اليهود ولا النصارى عشان أوريكم الفرق ؛ لأن كده الموضوع هيطول مننا أوي\n لكن هتلاقوا في الرابط في التعليقات من موقع الإسلام سؤال وجواب\nإزاي اليهود والنصارى كانوا بيعاملوا العبيد\nأنا بس هفكركم بالكلام إللي قلناه في بداية السيرة عن العبيد،\nقلت لكم إن الروم النصارى كانوا بيرموا العبيد للحيوانات يتصارعوا معاها وهم بيتفرجوا عليهم،\nوالعبيد بالنسبة لهم مكنش لهم أي حقوق مع إن العبيد في الدولة الرومانية كانوا ثلاثة أضعاف الأحرار،\nحتى أفلاطون الفيلسوف المعروف صاحب فكرة المدينة الفاضلة[اليوتوبيا] إللي كان بيتخيلها في عقله كان بيقول : \nإنه لا يجب أن يُعطى العبيد حق المواطنة،\nقارنوا بقى بين الكلام ده وبين إللي الإسلام عمله للعبيد، و أنا قلت لكم بس بعض حقوق العبيد إللي قال عنها الإسلام مش كلها\nأتمنى كده إن النقطة دي تكون وضحت،\nلو لسه في حاجة مش واضحة قولوا لي في التعليقات وهجاوب عليها إن شاء الله في بداية الجزء الجاي زي ما عملت النهاردة كده\nنرجع بقى للأحداث الداخلية إللي حصلت في السنة الثامنة للهجرة، \nمن الأحداث إللي حصلت بناء مِنْبَر لرسول الله ﷺ،\nفي البداية كان رسول الله ﷺ يَخطب في أصحابه وهو قائم على قدميه،\nفإذا أطال الوقوف و حسَّ بالجَهد والتَّعب، استند على إحدى سواري المسجد يعني أعمدة المسجد، وسواري المسجد كانت مصنوعة من جذوع النخل،\nيعني رسول الله ﷺ كان بيسند على جذع نخلة إذا تعب من كثرة الوقوف،\nفلما زاد عدد الناس إللي دخلوا في الإسلام وبقت الوفود تأتي لرسول الله ﷺ وهو محتاج يعلمهم أمور الإسلام ويعظهم جاءت فكرة المنبر،\nوالمنبر هو مكان مرتفع عن الأرض له درجات زي درجات السلم كده وفي آخره مُسْتَرَاح، يعني زي بَسْطة كده أو مقعد يتقعد عليه،\nوفائدة المنبر لرسول الله ﷺ إن كده الصحابة هيقدروا يجتمعوا حول رسول الله ﷺ بأعداد كبيرة ويشوفوه ويستمعوا ويتعلموا منه بسهولة،\nووجود المستراح في آخر المنبر ساعد رسول الله ﷺ إنه لما يتعب يقعد عليه ويريح جسمه\nبالنسبة لمين هو صاحب فكرة بناء المنبر فاحنا عندنا روايات كتيرة عن إللي قال الفكرة دي، والروايات كلها صحيحة،\nففي رواية بتقول إن رسول الله ﷺ هو صاحب الفكرة وإنه قال لامرأة من الأنصار :\n\" مُري غُلامك النَّجَّارَ، أن يَعمل لي أعوادًا، أجلسُ عليهنَّ إذا كلَّمتُ النَّاس\"\nيعني هي كانت عندها عبد نجار، فرسول الله ﷺ قالها تخلي النجار ده يعمله زي كرسي كبير يقعد عليه رسول الله ﷺ وهو بيكلم الناس،\nفالغلام النجار عمل منبر لرسول الله ﷺ من الخشب وكان  الخشب إللي استعمله من شجر الأثْل إللي كان موجود في منطقة الغابة على أطراف المدينة،\nوشجر الأثْل شجر سيقانه قوية يُصنع منه الخشب الصلب،\nفعمل له المنبر وكان عبارة عن درجتين ومقعد، إللي هو المُستراح،\nوفي رواة تانية إن في امرأة هي إللي قالت لرسول الله ﷺ على فكرة المنبر،\nقَالَتْ: يَا رَسُولَ اللَّهِ، أَلا أَجْعَلُ لَكَ شَيْئًا تَقْعُدُ عَلَيْهِ؛ فَإِنَّ لِي غُلَامًا نَجَّارًا؟ قَالَ: \"إِنْ شِئْتِ\"\nالمهم إن في منبر اتعمل لرسول الله ﷺعشان يطلع يخطب عليه، \nفلما صعد رسول الله ﷺ على المنبر عشان يخطب الجمعة، في اللحظة دي الصحابة اتفاجؤوا بصوت بكاء وأنين زي صوت حنين الناقة كده لما حد ينتزع منها ولدها\nفقعدوا يشوفوا الصوت ده جاي منين\nفلقوا إن الصوت ده طالع من الجذع إللي رسول الله ﷺ كان بيسند عليه\nالجذع بقاله ثمان سنوات حول رسول الله ﷺ، فأحبه الجذع واستأنس بوجود رسول الله ﷺ بالقرب منه،\nفلما ابتعد عنه رسول الله ﷺ، حن له الجذع واشتاق،\nوفي رواية إن الجذع من حزنه وبكاؤه انشق\nالحجر والشجر كانوا بيسلموا على رسول الله ﷺ قبل النبوة لما كان بس بيعدي عليهم،\nفما بالكم بجذع كان رفيقه السنين دي كلها\nفلما سمع رسول الله ﷺ حنين الجذع نزل من على المنبر وراح للجذع ووضع يده على الجذع ومسح عليه وحضنه فسكن الجذع وهدأ،\nوقال رسول الله ﷺ:\n\"لَوْ لَمْ أَحْتَضِنْهُ لَحَنَّ إِلَى يَوْمِ الْقِيَامَةِ\"\nيعني لو مكنتش حضنته كده كان هيفضل يحن ويخرج منه الصوت ده إلى يوم القيامة،\nوبعدها أمر رسول الله ﷺ إن الجذع ده يُدفن\nواحد من التابعين إللي جاءوا بعد رسول الله ﷺ اسمه الحسن البصري، كان لما بيقعد يحدث الناس بحديث حنين الجذع لرسول الله ﷺ كان يبكي ويقول للناس:\n\"يا عبادَ الله، الخشبة تحنُّ إلى رسول الله ﷺ شوقًا إليه؛ لِمكانه من الله عز وجل، فأنتم أحق أن تَشتاقوا إلى لقائه!\"\n♡واحنا فعلا بنشتاق لرؤية رسول الله ﷺ وصحبته،\nربنا يجمعنا وإياكم مع رسول الله ﷺ في الفردوس الأعلى من غير سابقة عذاب ولا حساب\n☆ملحوظة:\n محصلش يا جماعة إن رسول الله ﷺ خيّر الجذع إنه يغرسه في المكان إللي كان فيه قبل ما يُوضع في المسجد،\nأو إنه يُغرس في الجنة فيشرب من أنهارها ويَنْبُت له ثمر فيأكل منه أهل الإيمان في الجنة، وإن الجذع اختار إنه يبقى في الجنة، \nالكلام ده جاء في رواية لا تصح عن رسول الله ﷺ \nوالرواية دي نصها:\n \nأنَّ النَّبِيَّ ﷺ حِينَ سَمِعَ حَنِينَ الْجِذْعِ ، رَجَعَ إِلَيْهِ ، فَوَضَعَ يَدَهُ عَلَيْهِ، وَقَالَ: \n اخْتَرْ أَنْ أَغْرِسَكَ فِي الْمَكَانِ الَّذِي كُنْتَ فِيهِ، فَتَكُونَ كَمَا كُنْتَ، وَإنْ شِئْتَ أَنْ أَغْرِسَكَ فِي الْجَنَّةِ ، فَتَشْرَبَ مِنْ أَنْهَارِهَا وَعُيونِهَا فَيَحْسُنَ نَبْتُكَ، وَتُثْمِرَ ، فَيَأْكُلَ أَوْلِيَاءُ اللَّهِ مِنْ ثَمَرَتِكَ وَنَخْلِكَ فَعَلْتُ.\nفَزَعَمَ أَنَّهُ سَمِعَ مِنَ النَّبِيِّ ﷺ ، وَهُوَ يَقُولُ لَهُ:  نَعَمْ قَدْ فَعَلْتُ مَرَّتَيْنِ.\nفسئل النَّبِيُّ ﷺ ، فَقَالَ:  اخْتَارَ أَنْ أَغْرِسَهُ فِي الْجَنَّةِ\"\nفالرواية دي \n لا تصح عن رسول الله ﷺ، الرواية الصحيحة فيها إن الجذع حن ورسول الله ﷺ احتضنه ومسح عليه فهدأ وسكن الجذع فقط\nونص الحديث الصحيح:\n\" أَنَّ النَّبِيَّ ﷺ كَانَ يَخْطُبُ إِلَى جِذْعٍ ، فَلَمَّا اتَّخَذَ الْمِنْبَرَ ، ذَهَبَ إِلَى الْمِنْبَرِ ، فَحَنَّ الْجِذْعُ، فَأَتَاهُ ،فَاحْتَضَنَهُ ، فَسَكَنَ\nفَقَالَ:  لَوْ لَمْ أَحْتَضِنْهُ لَحَنَّ إِلَى يَوْمِ الْقِيَامَةِ\"\nطبعا يا جماعة منبر رسول الله ﷺ إللي اتعمل مش هو المنبر الموجود دلوقتي في المسجد النبوي \nالمنبر بتاع رسول الله ﷺ كان اتجدد في زمن الدولة العباسية، وبعدين قبل سقوط الخلافة العباسية بحوالي سنتين حصل حريق في المسجد النبوي،\nوالحريق ده دمر شكل المسجد النبوي إللي كان رسول الله ﷺ أسسه،\nواحترق منبر رسول الله ﷺ بالكامل، وسبب الحريق كان إن بعد ما المصلين صلوا تراويح أول ليلة من رمضان من سنة 654هـ واحد من خدّام المسجد ذهب إلى مخزن موجود غرب المسجد،\nوكان في إيده نار تضيء له الطريق، فكان عايز يطلع قناديل أو مصابيح يُضيء بها جوانب المسجد زي ما كان متعود،\nالقناديل دي حاجة عاملة زي لمبة الجاز بتاعة زمان كده\nالمهم وهو بيطلع القناديل دي نسي النار إللي كان ماسكها في إيده داخل المخزن وخرج،\nمفيش غير لحظات والمخزن اشتعل، والنار وصلت لسقف المسجد وأسقطته، \nواتجهت النار ناحية جنوب المسجد، وجاء أمير المدينة والناس اتجمعوا وحاولوا يطفوا النار لكن مفيش فايدة واحترق المسجد كله ومتبقاش فيه خشبة واحدة سليمة\nوبقيت أعمدة المسجد قائمة تتمايل مع الريح زي جذوع النخل كده،\nولم ينجُ من الحريق ده غير قُبة توضع فيها الذخائر كانت موجودة في وسط المسجد، والغرفة إللي رسول الله ﷺ مدفون فيها\nالخليفة العباسي ساعتها وكان اسمه المستعصم بالله أسرع بإرسال الأموال لترميم المسجد،\nلكن ملحقش يكمله لأن التتار كانوا بدأوا الهجوم على مناطق نفوذ الدولة العباسية في نفس الوقت إللي حصل فيه الحريق، وتقدم التتار لحد ما وصلوا بغداد بعد الحريق بسنتين وأعدموا المستعصم بالله وكان آخر خليفة عباسي،\nوتوقفت إصلاحات المسجد لحد ما جاء المماليك وأنهوا الإصلاحات بمساعدة ملك اليمن إللي كان أرسل منبر جديد بدل المنبر إللي احترق، \nوبعدها بحوالي مائتين سنة احترق المسجد النبوي مرة تانية، بسبب صاعقة ضربت هلال منارة المسجد، وكانت السماء مليانة بالغيوم والأمطار والصواعق،\nواحترق المنبر، وبعدها بنى أهل المدينة منبر بدل إللي احترق ده، \nوبعدها بفترة أرسل سلطان مصر قَيْتَباي منبر من الرخام و تم وضعه بدل منبر أهل المدينة،\nوالكلام ده كان سنة 888 من الهجرة،\nبعدها بحوالي مائة سنة أرسل السلطان مراد العثماني منبر مصنوع من الرخام كان في غاية الإبداع ودقة صناعته، وروعة زخرفته ونقوشه، وطُلي بماء الذهب،\nفنُقل منبر قايتباي إلى مسجد قباء، ووضع منبر السلطان مراد مكانه،\nوهو المنبر الموجود دلوقتي في المسجد النبوي، هتلاقوا صورته في التعليقات \nوبكده يبقى عرفنا قصة منبر رسول الله ﷺ من البداية للنهاية باختصار\nلتفاصيل أكتر راجعوا الروابط في التعليقات\nإن شاء الله المرة الجاية هنكمل كلام عن الأحداث الداخلية في المدينة بعد عودة رسول الله ﷺ من مكة"}, {"n": 210, "l": "الجزء 184 | احداث السنه الثامنه من الهجرة | كفى بالله شهيدا كفي بالله كفيلا", "u": "", "t": "#قصص_الأنبياء(٢)\n#السيرة_النبوية\n#الحلقة_مائة_وأربعة_وثمانون\n#أحداث_السنة_الثامنة_من_الهجرة\n#كفى_بالله_شهيدا_كفى_بالله_كفيلا\nاتكلمنا المرة إللي فاتت عن بناء المنبر، والنهاردة هنشوف بعض الأحداث إللي حصلت في المدينة بعد عودة رسول الله ﷺ،\nفاكرين لما قلنا عن إن رسول الله ﷺ أهدر دم مجموعة من قريش، وعرفنا قصص معظمهم\nفي واحد كان رسول الله ﷺ أهدر دمه اسمه كعب بن زُهَيْر،\nوكعب ده يبقى ابن الشاعر المشهور زُهَيْر بن أبي سُلْمَى من قبيلة مُزَيْنة،\nوكعب نفسه كان شاعر مشهور في الجاهلية، فلما ظهر الإسلام هجا رسول الله ﷺ يعني قعد يذم فيه ويقول شعر يعبر عن سخطه واشمئزازه منه ﷺ،\nوقعد يعمل قصائد يتغزل فيها بنساء المسلمين ويتكلم في أعراضهن،\nوالشعر زمان كان زي وسائل الإعلام عندنا كده، أو زي الفيس بوك، واحد ينزل منشور والكل يشاركه،\nفزمان لما كان الواحد يقول قصيدة كانت تنتشر بسرعة وسط العرب،\nفتخيلوا بقى انتم تشوفوا منشورات بتشتم في رسول الله ﷺ ليل نهار هيبقى إحساسكم إيه\n فرسول الله ﷺ أهدر دمه مع إللي كان أهدر دمهم قبل ما يدخل مكة،\nوأخو كعب كان أسلم و اسمه بُجَيْر بن زُهَيْر، فلما رجع رسول الله ﷺ من الطائف أرسل بُجَيْر لأخيه كعب قصيدة يخبره فيها إن رسول الله ﷺ قتل رجال في مكة من إللي كانوا بيهجوه وبيؤذوه،\nوإن إللي اتبقي من شعراء قريش إللي كانوا بيهجوه هم: \nابن الزِّبَعْرى وهُبَيْرَة بن أبي وهب؛ لأنهم هربوا يوم الفتح،\nفتعال بسرعة لرسول الله ﷺ فهو لا يقتل أحد جاءه تائبا مسلما، ولو معملتش كده فروح شوف لك مكان تنجو فيه من رسول الله ﷺ، ده لو عرفت\n☆ملحوظة:\nعبد الله بن الزِّبَعْرى وهُبَيْرَة بن أبي وهب الاتنين هربوا يوم فتح مكة وتوجهوا لمدينة نَجْران،\nوالاتنين دول كانوا بيهجُوا رسول الله ﷺ وبيؤذوه وبيؤذوا المسلمين بشعرِهم وكانوا من المُعادين للإسلام،\nعبد الله بن الزِّبَعْرى ربنا هداه للإسلام فترك مدينة نجران وترك صاحبه هُبَيْرَة ورجع لرسول الله ﷺ في المدينة واعتذر منه وأسلم فعفا عنه رسول الله ﷺ،\nأما هُبَيْرَة فقعد في مدينة نجران لحد ما مات على الكفر، \nو هُبَيْرَة بن أبي وهب ده يبقى زوج أم هانئ أخت علي بن أبي طالب، يعني يبقى زوج بنت عم رسول الله ﷺ، ومع ذلك كان بشتمه ويؤذيه الاذى ده كله\nالمهم بقى لما وصلت رسالة بُجَيْر لكعب ضاقت به الأرض، وخاف على نفسه، وبعدها خرج من الأرض إللي كان فيها وتوجه للمدينة فنزل ضيف على رجل كان في بينه وبينه معرفة،\nوتاني يوم الصبح أخذه الرجل وراح لرسول الله ﷺ في صلاة الصبح، \nفصلى مع رسول الله ﷺ، وبعدها شاور لكعب على رسول الله ﷺ وقال له: \n\"هذا رسول الله، فقم إليه فاسْتَأمِنه\"\nفقام كعب إلى رسول الله ﷺ فجلس إليه، ووضع يده في يد رسول الله ﷺ، ورسول الله ﷺ مكنش يعرفه،\nفقال كعب: \nيا رسول الله، إن كعب بن زهير قد جاء ليَستَأمن منك تائبا مسلما فهل أنت قابلٌ منه إن جئتُك به؟\nيعني بيقول لرسول الله ﷺ إن كعب تاب وأسلم وجاء يطلب العفو والأمان، فهل لو أنا جبته وجيت لك هتعفو عنه وتعطيه الأمان؟\nفقال له رسول الله ﷺ: نعم\nفقال كعب: إذا أنا يا رسول الله كعب بن زهير\nوقال كعب قصيدته المشهورة :《 بَانَت سعاد》يمدح فيها رسول الله ﷺ،\nويُقال والله أعلم بصحة الموضوع إن بعد ما أنهى كعب قصيدته أعطاه رسول الله ﷺ البُرْدَة بتاعته هدية، والبردة دي زي عباية مفتوحة يُلتحف بها،\nوالقصيدة فعلا جميلة، ومن أبياتها:\nُكلِّ ابن أُنثَى وإن طَالَت سلامَتُه*يوماً على آلةٍ حَدْبَاءَ محمول\nُنُبِّئتُ أن رسولَ الله أوْعدني * والعفوُ عند رسول الله مأمول\n☆ملحوظة:\n في التعليقات \n هتلاقوا رابط لفيديو لبعض أبيات القصيدة بينشدها المنشد أبو عبد الملك، هتعجبكم إن شاء الله زي ما عجبت رسول الله ﷺ \nوالقصيدة كاملة موجودة في الجزء الرابع من كتاب البداية والنهاية لابن كثير.\nوبكده يبقى احنا خلصنا أهم الأحداث ومعظمها في السنة الثامنة من الهجرة، سواء الأحداث الداخلية أو الخارجية،\nوهننهي الكلام عن السنة الثامنة للهجرة بقصة إيمانية عجيبة من قصص بني إسرائيل حكاها رسول الله ﷺ  للصحابة،\nوالمرة الجاية إن شاء الله هنبدأ الكلام عن أحداث السنة التاسعة من الهجرة\nالقصة بيرويها أبو هريرة عن رسول الله ﷺ،\nقال: قال رسول الله ﷺ:\n\"إنّ رَجُلًا مِنْ بَنِي إِسْرَائِيلَ سَأَلَ بَعْضَ بَنِي إِسْرَائِيلَ أَنْ يُسْلِفَهُ \nأَلْفَ دِينَارٍ،\nفَقَالَ : ائْتِنِي بِالشُّهَدَاءِ أُشْهِدُهُمْ.\nفَقَالَ : كَفَى بِاللَّهِ شَهِيدًا. قَالَ : فَأْتِنِي بِالْكَفِيلِ . قَالَ : كَفَى بِاللَّهِ كَفِيلًا.\nقَالَ : صَدَقْتَ . فَدَفَعَهَا إِلَيْهِ إِلَى أَجَلٍ مُسَمًّى....\"\nيعني رسول الله ﷺ بيقول إن واحد من بني إسرائيل سأل واحد إنه يسلفه ألف دينار،\nيعني يا جماعة ما يساوي حوالي اثنين مليون وخمسائة ألف جنيه مصري\nلأن الدينار الواحد يساوي أربعة جرام وربع الجرام، وبعملية حسابية كده هنقدر نعرف الألف دينار تساوي كم في زمننا دلوقتي،\nوأنا بقولكم المبلغ أد إيه عشان تعرفوا إن المبلغ مش بسيط، وعشان تعرفوا إيمانيات الرجلين دول وثقتهم وتوكلهم على ربنا عامل إزاي\nالمهم،\nالرجل لما طلب الألف دينار، صاحبه قاله هات شهود يشهدوا إنك أخدت مني فلوس، وطبعا ده طبيعي وحقه\nوربنا بيقول في آية الدّيْن وهي أطول آية في القرآن:\n\"يَا أَيُّهَا الَّذِينَ آمَنُوا إِذَا تَدَايَنتُمْ بِدَيْنٍ إِلَى أَجَلٍ مُسَمّىً فَاكْتُبُوهُ\"\nيعني لما يبقى في دين بين اتنين اكتبوا الدين ده وأشهدوا عليه ناس،\nفالرجل إللي جاي يستلف رد عليه وقاله، كفى بالله شهيدا، يعني كفاية ربنا شاهد علينا،\nفالرجل صاحب المال قاله طيب هات كفيل يكفلك، يعني حد  يضمنك إنك هترجع لي المال تاني،\nفالرجل قاله ربنا كفيلي وهو بيكفّي، فصاحب المال قاله معاك حق، كفى بالله شهيدا وكفيلا،\nوصاحب المال هنا مقلش مثلا : أنا عارف إن ربنا كفيلٌ وشهيدٌ؛ بس أنا عايز أوثّق دَيْني وأثبت حقي\nلأ، ده إيمانهم كان عالي أوي فكانوا يعظّموا اسم ربنا من إنه يتحط في موضع خيانة أمانة أو أكل أموال الناس بالباطل\nطبعا ده ميمنعش يا جماعة إن الواحد يوثِّق دينَه وهو يعتقد إن ربنا كفيل\nلأن في ناس لا يُجِلُّون الله تبارك وتعالى، ويرضوا إن اسم ربنا العظيم يُهانَ عادي \nالمهم، الرجل أعطاله الألف دينار واتفقوا إن الرجل يرجعهاله في وقت معين،\nبعد شهر أو شهرين أو سنة، الله أعلم بالمدة كانت أد إيه\nالمهم رسول الله ﷺ كمل القصة للصحابة وقال:\n\"فَخَرَجَ فِي الْبَحْرِ فَقَضَى حَاجَتَهُ ، ثُمَّ الْتَمَسَ مَرْكَبًا يَرْكَبُهَا يَقْدَمُ عَلَيْهِ لِلْأَجَلِ الَّذِي أَجَّلَهُ،\n فَلَمْ يَجِدْ مَرْكَبًا فَأَخَذَ خَشَبَةً، فَنَقَرَهَا فَأَدْخَلَ فِيهَا أَلْفَ دِينَارٍ وَصَحِيفَةً مِنْهُ إِلَى صَاحِبِهِ، ثُمَّ زَجَّجَ مَوْضِعَهَا ثُمَّ أَتَى بِهَا إِلَى الْبَحْرِ فَقَالَ: \nاللَّهُمَّ إِنَّكَ تَعْلَمُ أَنِّي كُنْتُ تَسَلَّفْتُ فُلَانًا أَلْفَ دِينَارٍ ، فَسَأَلَنِي كَفِيلَا فَقُلْتُ :\nكَفَى بِاللَّهِ كَفِيلًا فَرَضِيَ بِكَ،\nوَسَأَلَنِي شَهِيدًا فَقُلْتُ :\nكَفَى بِاللَّهِ شَهِيدًا فَرَضِيَ بِكَ، وَأَنِّي جَهَدْتُ أَنْ أَجِدَ مَرْكَبًا أَبْعَثُ إِلَيْهِ الَّذِي لَهُ فَلَمْ أَقْدِرْ، وَإِنِّي أَسْتَوْدِعُكَهَا،\nفَرَمَى بِهَا فِي الْبَحْرِ حَتَّى وَلَجَتْ فِيهِ ثُمَّ انْصَرَفَ، وَهُوَ فِي ذَلِكَ يَلْتَمِسُ مَرْكَبًا يَخْرُجُ إِلَى بَلَدِهِ....\"\nيعني الرجل أخد المال واشتغل وتاجر بيه، وقضى مصلحته من المال، وجاء وقت سداد المال،\nفعشان يوصل لصاحب المال كان لازم يركب مركب يوصله له، واليوم ده كان البحر هائج ومكنش في مراكب، فقعد يبحث عن مركب واجتهد في البحث ملقاش ولا سفينة يركبها،\nوهو عايز يرجّع المال للرجل إللي مستني الناحية التانية ده، فأخد خشبة وحفر فيها في النص كده ووضع المال داخلها ومعاها رسالة منه لصاحبه بتشرح له ظروفه، وقفل عليها بخشبة تانية ودق عليها بمسامير،\nوجاء بالخشبة دي للبحر وبدأ يكلم ربنا ويقوله يارب انت عارف إني استلفت من فلان ألف دينار، \nوطلب مني حد يشهد عليّ قلت له كفى بالله شهيدا فرضي إنك تكون انت الشاهد علينا، وطلب إن يكون في كفيل يضمني قلت له كفى بالله كفيلا فرضي بك،\nوأنا اجتهدت في البحث عن مركب عشان أرجعله الفلوس ملقتش، فيارب أنا جعلت الخشبة دي بالأموال إللي فيها وديعة عندك عشان توصلها لصاحب المال\n☆وإن الله إذا اسْتُودِع شيئًا حَفظَه\nراح الرجل بقى رمي الخشبة في البحر وهي فيها الألف دينار، يعني فيها اتنين مليون وخمسمائة ألف جنيه\nطبعا لو حد فينا عمل الكلام ده الناس هتتهمه على طول بالجنون وبتضييع المال\nلكن هو ده الفرق بين رؤية المؤمن المتوكل على ربه وغير المؤمن أو ضعيف الإيمان\nوفي نفس الوقت وعلى الرغم من شدة إيمانه فالرجل مسكتش وقال خلاص أنا كده تمام و ربنا هيوصل المال فأنا معليش ذنب\nلأ، ده استمر في البحث عن مركب عشان يروح للرجل المستني الناحية التانية عشان يديله الألف دينار في إيده زي ما أخدهم منه؛ \nلأن مينفعش الاعتماد على الخوارق في قضاء الدّيْن\nيعني لا يجوز إن الواحد يروح بمال الدين ويرميه على الطريق ويقول: إن شاء الله هيوصل، وإذا جاء صاحب الدين يسأل : فين الدين بتاعي،\nفنقول: والله أنا وضعته لك في مكان كذا وكذا، هو موصلكش ولّا إيه\nلا يجوز الإعتماد على الطريقة دي في قضاء الدين\nو الرجل ده عارف الكلام ده كويس عشان كده قعد يبحث عن طريقة يوصل بيها لصاحب المال،\nفهنسيب صاحبنا ده يبحث عن مركب ونروح نشوف الرجل صاحب المال عامل إيه في الورطة دي\nما هو ميعرفش حاجة عن الرجل إللي استلف منه الفلوس، وميعاد إرجاع المال جاء والتاني مظهرش\n\"فَخَرَجَ الرَّجُلُ الَّذِي كَانَ أَسْلَفَهُ يَنْظُرُ لَعَلَّ مَرْكَبًا قَدْ جَاءَ بِمَالِهِ،\n فَإِذَا بِالْخَشَبَةِ الَّتِي فِيهَا الْمَالُ، فَأَخَذَهَا لِأَهْلِهِ حَطَبًا، فَلَمَّا نَشَرَهَا وَجَدَ الْمَالَ وَالصَّحِيفَةَ....\"\nيعني الرجل صاحب المال خرج يشوف إذا كان الرجل إللي استلف منه المال جاء بماله أو بعت له ماله مع حد ولّا لأ،\nفملقاش حد ويأس إن الرجل يأتي له بالمال، فشاف خشبة قصاده على وش المية،\nفأخذ الخشبة دي عشان يستعملها كحطب يتدفأ بيها هو وأهله، فلما رجع لبيته وبدأ ينشر الخشبة لقى المال والرسالة،\nفعرف إن المال ده من صاحبه\n☆سبحان الله،\nفعلا بقدر ما يكون لك من الإخلاص والثبات، والوفاء بالوعد، والحفاظ على أموال الناس ومشاعرهم بقدر ما يكون ربنا معاك ويعينك على كده،\nوبقدر ما يحتوي قلب العبد على الغل والغش والخداع بقدر ما يبتعد عنه تأييد الله ونصره\nالرجل هنا كان بيتحرّق شوقا إنه يرد المال في ميعاده ومش عايز اسم ربنا العظيم إللي أخذ بيه المال يُدَنّس بأي شكل من الأشكال،\nفبسبب صدق قلبه؛ ربنا إللي من أسمائه 《الكفيل 》تكفل بإنه يوصّل المال لصاحبه\nرسول الله ﷺ كمل القصة للصحابة فقال:\n\" ثُمَّ قَدِمَ الَّذِي كَانَ أَسْلَفَهُ فَأَتَى بِالْأَلْفِ دِينَارٍ ، فَقَالَ : \nوَاللَّهِ مَا زِلْتُ جَاهِدًا فِي طَلَبِ مَرْكَبٍ لِآتِيَكَ بِمَالِكَ فَمَا وَجَدْتُ مَرْكَبًا قَبْلَ الَّذِي أَتَيْتُ فِيهِ. \nقَالَ : هَلْ كُنْتَ بَعَثْتَ إِلَيَّ بِشَيْءٍ ؟ \nقَالَ : أُخْبِرُكَ أَنِّي لَمْ أَجِدْ مَرْكَبًا قَبْلَ الَّذِي جِئْتُ فِيهِ!\nقَالَ : فَإِنَّ اللَّهَ قَدْ أَدَّى عَنْكَ الَّذِي بَعَثْتَ فِي الْخَشَبَةِ فَانْصَرِفْ بِالْأَلْفِ الدِّينَارِ رَاشِدًا\"\nيعني بعدها بشوية كان الرجل لقى مركب وركبه وجاء بألف دينار تانية عشان يرجعها لصاحبه،\nفأول ما شافه حلف له بالله إنه عمال يدوّر على مركب عشان ييجي ويرجع له المال وملقاش مركب غير إللي لسه جاي فيها دلوقتي،\nفصاحب المال سأله إذا كان بعت له حاجة قبل ما ييجي، فالرجل مقلوش لأ، وإلا كده يبقى كذب، ولكن قاله كلام يتفهم منه إنه مبعتش حاجة، فقاله: أنا بقولك ملقتش مركب غير إللي جيت لك عليها دلوقتي\nفقال صاحب المال:\nخلاص ربنا أدّى عنك الدين بتاعك، ووصلني المال إللي انت كنت بعتهولي في الخشبة، فخلاص خد الألف دينار التانية دي وارجع\nهنا الصحابة بقى لما سمعوا القصة دي قعدوا يتناقشوا بينهم قصاد رسول الله ﷺ، يا ترى مين أكثر إيمان فيهم\nهل الرجل إللي رمى بالألف دينار في البحر وهو موقن أن الله لن يضيعه؟\nولّا الرجل إللي لقى المال ولم يجحده وينكره وطلع أمين \nماهو الرجل صاحب المال كان ممكن ميقولش على الألف دينار إللي لقاها في الخشبة دي، ومفيش حد عارف حاجة\nفي رأيكم بقى، مين أشد الرجلين إيمانا \nأنا شخصيا رأيي إن الرجل إللي رمى بالمال في البحر هو أكثر الرجلين إيمانا؛\nلأنه كان متوكل ومُعتمد بقلبه اعتماداً كلياً على ربه، وده الهدف من القصة دي أصلا\nرسول الله ﷺ مكنش يعرف القصة، وربنا هو إللي أطلَعه عليها من خلال الوحي،\nفربنا يريد إنه يعلمنا كلنا إن إللي يتوكل عليه بصدق سبحانه  مش هيضيعه أبدا\nومش معنى التوكل إننا نسيب الأخذ بالأسباب\nالتوكل الحقيقي هو اعتماد القلب بالكلية على الله عز وجل مع البراءة من الاعتقاد بالسبب\nيعني مثلا الشغل سبب في المال فالواحد بيشتغل عشان يجيب المال،\nلكن ميبقاش في قلبه إنه لو ساب الشغل هتبقى نهاية العالم ومش هيلاقي ياكل ومش هيبقى في أي مصدر تاني للرزق،\nوممكن يعصي ربنا عشان يستمر في الشغل،\nفده كده قلبه متعلق بالأسباب\nوعشان المعنى يوضح أكتر شوفوا رسول الله ﷺ قال إيه لرجل سأله عن الناقة بتاعته وقال:\nيا رسول الله! أترك ناقتي وأتوكل؟\nيعني أسيب الناقة بتاعتي تمشي في الأرض كده مع نفسها وأنا متوكل على ربنا إنه هيحفظها لي ومحدش هيسرقها أو مش هتضيع، وده كده يكون من التوكل؟ \nفقال له رسول الله ﷺ: 《اعقلها وتوكل》\nيعني بيقوله لأ، انت تربطها بحبل وتتوكل على الله إنه يحفظها، \nفاحنا منتصورش إن الحبل هو إللي بيحفظ الناقة؛ لأن ناس كتيرة ربطوا جِمالهم وبرده ضاعت! \nلكن لازم مع الأخذ بالأسباب إن الواحد يعتقد إن ربنا هو الحفيظ...هو الرازق...هو....هو....\nلازم واحنا بنعمل الشيء نبقى عارفين كويس أوي إن ربنا  تبارك وتعالى هو المتصرف في الكون ده\nفيبقى نطلع من القصة دي يا جماعة بخمس نقط سريعة:\n♡ أولا:\nنعتمد على ربنا في كل أمورنا ولا نعتمد على نفسنا ولا على حولنا وقوتنا، ونجعل ربنا كفيلنا وحسيبنا ونصدُق في كده وربنا مش هيضيعنا أبدًا.\n♡ثانيا:\nإن إللي بياخد من حد دين وهو ناوي إنه يرجعه؛ ربنا بيعينه على أداء الدين ده.\n♡ثالثا:\nالوفاء بالوعد:\nفالرجل لما جاء موعد سداد الدين و ملقاش حاجة توصله لصاحبه كان حريص على الوفاء بوعده بأي طريقة، لدرجة إنه رمى الألف دينار في الماء.\n♡رابعا: الأمانة:\n لما صاحب المال اعترف للآخر بأنه لقى المال في الخشبة ولم يُنكر ولم يأخذ منه الألف الأخرى.\n♡خامسا:\nلما الواحد بيحافظ على عهده ووعده ويصدُق مع ربنا، ربنا بيسخّر له حتى الجماد،\nفالرجل لما حفظ عهده ووفّى بوعده حفظ الله له ماله وساق الخشبة على الأمواج لحد ما وصلت لصاحب الدين ومراحتش لا يمين ولا شمال، فسبحان من سيّرها\nنسأل الله أن يوفقنا جميعا لما يحب ويرضى، وأن يعيننا على الأخذ بالأسباب وأن نتوكل عليه سبحانه حق توكله"}, {"n": 211, "l": "الجزء 185 | احداث السنه الثامنه من الهجرة | الحسنات يذهبن السيئات", "u": "", "t": "#قصص_الأنبياء(٢)\n#السيرة_النبوية\n#الحلقة_مائة_وخمسة_وثمانون\n#أحداث_السنة_التاسعة_من_الهجرة\n#الحسنات_يُذهبن_السيئات\nهنبدأ الكلام النهاردة إن شاء الله عن أحداث السنة التاسعة من الهجرة، والعام التاسع من الهجرة ده اسمه عام الوُفُود،\nواتسمى بالاسم ده بسبب كثرة الوُفُود إللي جاءت للمدينة عشان تعلن إسلامها عند رسول الله ﷺ،\nبعض الوفود جاءت قبل غزوة تبوك،\nلكن أكثر الوفود جاءت للمدينة بعد غزوة تبوك إللي هنعرف أحداثها بعدين إن شاء الله\nفي شهر محرم من السنة التاسعة من الهجرة بعث رسول الله ﷺ بِشْر بن سفيان العَدوِي الكلبي إلى بني كعب من خزاعة عشان ياخد منهم الزكاة،\nفلما وصل عندهم طلب منهم الزكاة فبدأوا يجمعوا له أموال الزكاة،\nفلما جمعوها لبِشر؛ بنو تميم إللي كانوا جيران لبني كعب لما شافوا الزكاة إللي أخذها بشر استكثروها على المسلمين،\nيعني شافوا إنها كتير أوي و ليه وبتاع إيه المسلمين ياخدوا الأموال دي كلها\nفقالوا لبني كعب: لمَ تُعطونَهم أموالكم؟\nيعني انتم بتدوهم أموالكم ليه؟\nوراحوا قايمين على بِشر بالسلاح ومنعوه إنه يأخذ الزكاة،\nفبنو كعب قالوا لهم: \nاحنا أسلمنا و لازم في ديننا إننا ندفع الزكاة\nفقال بنو تميم:\nوالله لا ندعُ بعيرا واحدا يخرج\nيعني زي ما بنقول كده مش هنسيبه ياخد ولا ملّيم \nودي مش فلوسهم أصلا ولا دفعوا حاجة من جيبهم\nوبنو كعب نفسهم راضيين إنهم يدفعوا الأموال دي، \nبس نقول إيه، في ناس كده لازم تدّخّل في إللي ملهاش فيه\nالمهم،\nبِشر لما لقى الوضع كده؛ رجع للمدينة وأخبر رسول الله ﷺ باللي حصل،\nفجهز رسول الله ﷺ سرية من خمسين فارس من العرب فقط، مكنش فيهم مهاجرين ولا أنصار،\nوخلّى عيينة بن حصن الفزاري قائد للسرية و أمره إنه يتوجه لبني تميم لقتالهم،\nواختار رسول الله ﷺ فرسان عرب ولم يرسل أحد من المهاجرين ولا الأنصار؛ لأن أنسب ناس يقدروا يقاتلوا أعراب بني تميم أهل الحرب، هم فرسان أعراب مثلهم، وليس صحابة رسول الله ﷺ من المهاجرين والأنصار \nواختيار عُيينة بن حصن بالذات كقائد لهم؛ لأن له ماض معروف في الحروب\nخرجت السرية من المدينة، فكان عيينة بيمشي في الليل ويَكمُن في النهار،\nلحد ما وصل عند بني تميم فهجم عليهم وهرب بنو تميم،\nو أَسر عيينة أَحَدَ عشر رجل وإحدى عشرة امرأة،\nوثلاثين طفل ورجع بيهم للمدينة،\nلما رجع للمدينة أمر رسول الله ﷺ بحبس الأسرى في دار \"رَملة بنت الحارث\" والدار دي هي واحدة من دُور الضيافة إللي كانت لرسول الله ﷺ في المدينة،\nبعدها جاء وفد من رؤساء تميم للمدينة وكانوا حوالي سبعين أو ثمانين رجل،\nوجاءوا ليعتذروا لرسول الله ﷺ ويطلبوا العفو عن السبايا، فعفا رسول الله ﷺ عن الأسرى، وتركهم يرجعوا لقبيلتهم، وأسلم وفد بني تميم وقعدوا في المدينة فترة يتعلموا القرآن\nكمان رسول الله ﷺ بعث الوليد بن عقبة بن أبي مُعَيْط لبني المُصطلق عشان يجمع منهم الزكاة همّ كمان،\nو الوليد كان أسلم يوم الفتح وأبوه عقبة كان من إللي آذُوا رسول الله ﷺ جدا، \nولو تفتكروا عقبة ده هو إللي وضع أمعاء البعير على ظهر رسول الله ﷺ وهو ساجد عند الكعبة،\nوهو إللي خنق رسول الله ﷺ برداءه وهو ساجد عند الكعبة في مرة تانية، وقُتل في غزوة بدر\nالمهم،\nالوليد توجّه لبني المُصطلق عشان ياخد منهم الزكاة، فوصل الخبر لبني المُصطلق بمجيء الوليد،\nوكان في عداوة بين الوليد وبينهم من أيام الجاهلية ومع ذلك فرحوا بمجيء الوليد وجهزوا الزكاة وخرج منهم عشرين رجل بالسلاح والإبل والأغنام لاستقبال الوليد،\nفلما شافهم الوليد خاف واتفزع وفكّرهم خارجين عشان يقتلوه، \nفراح راجع للمدينة وأخبر رسول الله ﷺ إن بني المصطلق ارتدوا ورفضوا يؤدوا الزكاة وخرجوا لقتل الوليد\nطبعا رسول الله ﷺ غضب وقعد الصحابة يتكلموا بغزو بني المُصْطلق،\nوفعلا رسول الله ﷺ كان لسه هيجهز سرية لغزو بني المصطلق، لقى المجموعة إللي كانت خرجت لاستقبال الوليد بالسيف جاية المدينة بعد ما وصل لهم الخبر إن رسول الله ﷺ هيغزوهم،\nفجاءوا وبدأوا يشرحوا لرسول الله ﷺ الموقف بالكامل والسبب إللي خلاهم يخرجوا بالسيوف وإن الموضوع كله كان سوء تفاهم،\nفهنا نزلت الآية:\n\" يَا أَيُّهَا الذِينَ آمَنُوا إِنْ جَاءَكُمْ فَاسِقٌ بِنَبَأٍ فَتَبَيَّنُوا أَنْ تُصِيبُوا قَوْمًا بِجَهَالَةٍ فَتُصْبِحُوا عَلَى مَا فَعَلْتُمْ نَادِمِينَ\"\n☆طبعا هنا لازم نقف ونوضح نقطة مهمة جدا\nفي ناس من إللي بيطعنوا في الصحابة بياخدوا من الآية إللي قلناها دي حجة وبيقولوا الصحابي الوليد بن عقبة فاسق بنص القرآن\nوطبعا الكلام ده غير صحيح \nفمش معنى إن الآية هنا كمعنى عااام بتدل على وجوب التثبّت من خبر الفاسق، إن ده معناه وَصْف الوليد بن عقبة رضي الله عنه بالفسق؛\nلأن الوليد هنا لم يتعمد الكذب، ولكنه توهّم وظن فحصل منه خطأ، والمُخطئ لا يُسمى فاسقاً\nفالمقصود بالفسق هنا في حق الوليد هو الفِسق اللُّغوِي إللي معناه الخروج عن الطاعة، \nوسماه فاسقاً لأنه أخبر بخبر بخلاف الواقع الصحيح للناس إللي أُرسل إليهم،\nوده عكس الفِسق الشرعي إللي معناه مَن ارتكب كبيرة أو أَصَرّ على صغيرة،\nفالصحابة مفيش فيهم فاسق ولا كاذب و كلهم عُدُول،\nودي حاجة خاصة بالصحابة بالذات،\nومش معنى كده إن الصحابة معصومين زي ما قلنا قبل كده، أو إنهم لا يقعوا في صغائر أو كبائر،\nلأ، بيقعوا وشوفنا أمثلة قبل كده، لكن همّ لهم من السوابق والفضائل ما يُوجب مغفرة أي خطأ يحصل منهم ده إذا حصل،\nحتى إنه يُغفر لهم من السيئات ما لا يُغْفَر لمَن بعدَهم؛\nوده لأن لهم من الحسنات التي تمحو السيئات ما ليس لمِنَ بعدَهم،\nواحنا كنا قبل كده قلنا إن رسول الله ﷺ قال إن لو الواحد من الصحابة تصدق بملئ كفه فقط هيكون أفضل من إللي هييجي بعدهم و يتصدق بوزن جبل أحد ذهب، ده غير إنهم خير القرون بشهادة رسول الله ﷺ \nفلو واحد منهم صَدر منه ذنب فكان بيتوب على طول أو يأتي بحسنات تمحوا الذنب ده، \nأو ربنا يغفر له بسبب سابق فضله، زي ما حصل مع حاطب بن أبي بلتعة لما أرسل رسالة لأهل مكة يخبرهم إن رسول الله ﷺ هيغزوهم،\nوبعدين رسول الله ﷺ قال إن ربنا غفر له بسبب إنه من أهل بدر،\nفالكلام ده، لما يحصل منهم ذنب، فما بالكم بقى لما الموضوع يبقى فيه اجتهاد وسوء تفاهم زي موقف الوليد كده\nوالمجتهد إذا أصاب له أجران ولو أخطأ له أجر واحد، والخطأ مغفور\nوخلونا ناخد مثالين عن وقوع بعض الصحابة في الصغائر والكبائر،\n◇المثال الأول :وقوع واحد من الصحابة في صغيرة من الصغائر:\nواحد من الصحابة جاء لرسول الله ﷺ وقال له إنه أَصَابَ مِنَ امْرَأَةٍ قُبْلَةً، ،فأنزل الله تعالى آية:\n\" أَقِمِ الصَّلاَةَ طَرَفَي النَّهَارِ وَزُلَفًا مِنَ اللَّيْلِ إِنَّ الْحَسَنَاتِ يُذْهِبْنَ السَّيِّئَاتِ\"\nفالصحابي قال لرسول الله ﷺ:\nرَسُولَ اللَّهِ ! أَلِي هَذَا ؟ قَالَ رسول الله ﷺ : لِجَمِيعِ أُمَّتِي كُلِّهِمْ\"\nيعني يا جماعة واحد من الصحابة قبّل امرأة لا تحل له، و دي معصية من الصغائر، مش زي يعني فاحشة الزنا،\nفجاء لرسول الله ﷺ تائب عايز حاجة يعملها عشان ربنا يطهره من الذنب ده،\nحتى في رواية تانية بيقول: \n\" أَصَبْتُ حَدًّا فَأَقِمْهُ عَلَيَّ\"\nيعني هو كان متصور إن كل فعل مُحرّم الواحد بيعمله لازم له حد يكفّره، زي حد السرقة وحد شرب الخمر وهكذا،\nفربنا أنزل الآية إللي بتقول إن الحسنات والأعمال الصالحة تكفّر صغائر الذنوب وتمحو عن صاحبها الإثم والمعصية\nبعكس كبائر الذنوب إللي يكفّرها التوبة الصادقة أو الحد الشرعي،\nوبعد الصلاة رسول الله ﷺ قال للصحابي: \" قَدْ غُفِرَ لَكَ\"\nيعني خلاص ربنا غفر لك؛ وده لأن صلاته مع جماعة المسلمين كانت سبب في مغفرة ذنبه لأنه صدق التوبة مع الله\nلكن يا جماعة مش معنى إن الأعمال الصالحة بتكفّر السيئات يبقى الإنسان يتهاون في الوقوع فيها \nخدوا بالكم إن صاحب الصغيرة إذا أصرّ على معصيته، ولم يُتبِعها بالتوبة والإنابة والأعمال الصالحة انقلبت الصغيرة في حقه لكبيرة، أو قربت إنها تكون كبيرة من الكبائر\nوابن عباس قال إن المعصية الصغيرة إللي الإنسان مستمر عليها ممكن تكون أضر على صاحبها من كبيرة وقع فيها مرة واحدة ومعملهاش تاني\nفالواحد لو أسرف على نفسه بالمعاصي وأصر على الذنوب بحجة إنها صغائر و إن ربنا هيغفر له بالحسنات إللي بيعملها؛ هو أصلا هيعرف منين إن ربنا تقبّل الحسنات دي \nأو ممكن جدا الحسنات إللي اتعملت دي لا تكفّر السيئات،\nما هو محدش يعرف\nلازم وحي يقول إن ربنا غفر له زي ما جاء الوحي وأخبر رسول الله ﷺ بإن ربنا غفر للصحابي بعد ما تاب وصلى\n《إللي عايز تفصيل أكتر هيلاقي في التعليقات \nرابط فيه التفصيل من موقع الإسلام سؤال وجواب》\n◇المثال التاني: وقوع واحد من الصحابة في كبيرة من الكبائر:\nواحد من الصحابة اسمه ماعز بن مالك الأسلَمِي جاء لرسول الله ﷺ وقال له:\nيا رسول الله ‏طهِّرني\nفقال له رسول الله ﷺ:\n\"وَيْحَكَ! ارْجِعْ فَاسْتَغْفِرِ اللهَ وَتُبْ إِلَيْهِ\"\nرسول الله ﷺ مكنش يعرف ماعز عمل إيه، هو فِهم منه إنه عمل ذنب، فالطبيعي إنه يروح يتوب ويستغفر\nفمشي ماعز بن مالك، وبعد شوية رجع لرسول الله ﷺ مرة تانية وقال له:\nيا رسول الله ‏طهِّرني\n‏فقال له رسول الله ﷺ :\n\"وَيْحَكَ ارْجِعْ فَاسْتَغْفِرِ اللهَ وَتُبْ إِلَيْهِ\"\nفمشي ماعز بن مالك، وبعد شوية رجع تالت مرة لرسول الله ﷺ وقال له: يا رسول الله ‏طهِّرني\nفرد عليه رسول الله ﷺ بنفس الرد، أربع مرات عالحال ده، في المرة الرابعة رسول الله ﷺ سأله:\nفِيمَ أُطَهِّرُكَ؟\nيعني عايزني أطهرك من إيه، فقال له ماعز بن مالك:\nمن الزِّنا\nيعني ماعز بيقول لرسول الله ﷺ إنه وقع في كبيرة الزنا وعايز رسول الله ﷺ يطهره من الكبيرة دي بإنه يقيم عليه الحد؛ \nلأن الحد من مُكفّرات الذنوب زي ما قلنا من شوية،\nفهنا بقى قبل ما رسول الله ﷺ ياخد أي قرار بدأ يتثبّت من صحة كلامه؛ لأن الموضوع فيه رَجم، مش حاجة بسيطة خالص\nفسأل رسول الله‏ الصحابة:أَبِهِ جُنُونٌ؟\nيعني هو مجنون فبيقول الكلام ده ومش واعي للي بيقوله؟\nفالصحابة قالوا له إنه مش مجنون، فقال رسول الله ﷺ:\nأَشَرِبَ خَمْرًا؟\nيعني هو شرب خمر فلعبت بعقله ومبقاش عارف هو بيقول إيه؟\nفقام رجلٌ ‏فَاسْتَنْكَهَهُ ‏‏فَلَمْ يَجِدْ منه ريح خمرٍ، يعني واحد منهم قام و شمّه فملقاش فيه أي ريحة للخمر،\nفسأل رسول الله ﷺ ماعز:\nأَزَنَيْتَ؟ فقال ماعز: نعم \nفقال له رسول الله ﷺ:\n\"لَعَلَّكَ قَبَّلْتَ أَوْ غَمَزْتَ أَوْ نَظَرْتَ\"\nيعني ممكن تكون عملت حاجة انت مفكرها زنا وهي مش زنا، زي التقبيل أو النظر مثلا،\nورسول الله ﷺ بيقوله كده لأنه ﷺ كان قال قبل كده:\n\" إِنَّ اللهَ كَتَبَ عَلَى ابْنِ ‏آدَمَ حَظَّهُ مِنَ الزِّنَا أَدْرَكَ ذَلِكَ لَا مَحَالَةَ؛ فَزِنَا الْعَيْنِ النَّظَرُ، \nوَزِنَا اللِّسَانِ المَنْطِقُ، وَالنَّفْسُ تَمَنَّى وَتَشْتَهِي، وَالْفَرْجُ يُصَدِّقُ ذَلِكَ كُلَّهُ وَيُكَذِّبُهُ\"\nفرسول الله ﷺ بيحاول يشوف له مخرج بإنه يمكن يكون فِهِم بعض كلام رسول الله ﷺ غلط وعلى الأساس ده اعترف على نفسه بالزنا\nويُستحب للحاكم إنه لا يُبادر بإقامة الحد الشرعي لو جاءه واحد من الرّعية يعترف على نفسه بإنه عمل شيء يستوجب الحد،\nلكن يُستحب له إنه يُعَرِّض للمُقر عشان يرجع عن إقراره، زي ما رسول الله ﷺ كان بيعمل كده،\nفلو أصر المُقر على إقراره، أقام الحاكم عليه الحد، وهو ده إللي رسول الله ﷺ عمله لما لقى ماعز مصمم على إقراره زي ما هنشوف بعدين،\nو هنا في فرق بين موقف رسول الله ﷺ مع ماعز وموقفه مع المرأة المخزومية إللي سرقت ورفض ﷺ شفاعة أسامة بن زيد رضي الله عنه وأصر على إقامة الحد،\nو ده لأن المرأة المخزومية لم تعترف على نفسها وفي بعض الروايات إنها أنكرت أصلا موضوع السرقة ولما فتشوا بيتها لقوا المال عندها،\nفكده ثبت الحَد بالبينة أو بالدليل، ففي فرق بين إللي ثَبت عليه الحد باعترافه، وإللي يثْبُت عليه الحد بالبينة،\nفالثاني هو إللي يجب إقامة الحد عليه أول ما يوصل أمره للحاكم\nإزاي بقى تم تطبيق الحد على ماعز وإيه إللي حصل بعدها، \nده إللي هنعرفه الجزء الجاي إن شاء الله"}, {"n": 212, "l": "الجزء 186 | احداث السنه الثامنه من الهجرة | حد الرجم", "u": "", "t": "#قصص_الأنبياء(٢)\n#السيرة_النبوية\n#الحلقة_مائة_وستة_وثمانون\n#أحداث_السنة_التاسعة_من_الهجرة\n#حد_الرجم\nاتكلمنا المرة إللي فاتت عن ماعز بن مالك إللي وقع في كبيرة الزنا وجاء لرسول الله ﷺ عشان كان عايز رسول الله ﷺ يطهّره من الذنب ده بإنه يقيم عليه الحد،\nفلما رسول الله ﷺ اتأكد منه إنه فعلا وقع في كبيرة الزنا أمر بإقامة الحد عليه وهو الرّجم بالحجارة حتى الموت؛ \nلأنه زنى وهو مُحْصَن، والمحصن معناه الرجل إللي تزوج قبل كده،\nسواء بقى لسه متزوج، أو تزوج وطلّق أو تزوج وامرأته ماتت.\nالمهم،\nالصحابة أخذوا ماعز بن مالك و رجموه بالحجارة، فأول ما حس بمَسّ الحجارة يعني حس بألمها هرب،\nفأتبعه الصحابة  واستمروا في رجمه بالحجارة لحد ما مات،\nفلما رجع الصحابة لرسول الله ﷺ وأخبروه بهروب ماعز لما بدأوا يرجموه؛ قال لهم رسول الله ﷺ:\n\" فَهَلَّا تَرَكْتُمُوهُ؟\"\nيعني كنتم اتركوه وخلوه يأتيني ونشوف الشبهة إللي عنده إيه يمكن يكون رجع في كلامه وخلاص ميبقاش عليه حد\n☆وهنا نقدر نفهم نقطة مهمة من رسول الله ﷺ، وهي:\n إن إللي بيُقِر و يعترف على نفسه من غير ما يكون في بيّنة ودليل على إللي عمله؛ لو رجع في كلامه وقال أنا معملتش؛ لا يُقام عليه الحد،\nوحتى لو شُرِع في إقامة الحد، يعني حتى لو بدأوا ينفذوا الحد زي ما الصحابة بدأوا كده، والمُعترف غيّر كلامه وقال لم أفعل، يتوقف إقامة الحد عليه\nوإلا فإزاي يعني يُقيموا الحد على واحد بينكر أصلا إنه عمل خطأ، وهو أساسا إللي جاء و اعترف على نفسه ومحدش يعرف عنه حاجة\nبعكس بقى لو في بيّنة ودليل، يعني لو في أربعة شهود شهدوا على إنسان بفعل الفاحشة فهنا يُقام عليه الحد حتى لو أنكر؛ لأن في بيّنة ولا يسقط الحد مادام وصل للحاكم\nلكن لو الشهود نفسهم بقى همّ إللي رجعوا في كلامهم وقالوا لا ده احنا كنا غلطانين ونتوب إلى الله، يبقى هنا لا يُقام عليه الحد ؛ \nلأن رجوع الشهود دول عن شهادتهم قدح فيهم؛ لأنهم كاذبون في واحدة من الشهادتين، \nإن كان في الأول فهم كاذبون فلا تُقبل شهادتهم، وإن كان في الثاني فهم كاذبون فلا تُقبل شهادتهم\n《الموضوع فيه تفصيل كبير بين العلماء إللي عايز يتوسع ويعرف الأدلة وأقوال العلماء هيلاقي رابط التفصيل ده في التعليقات\n》\nبعد رجم ماعز قال رسول الله ﷺ لهَزَّالُ :\n\" وَاللهِ! يَا ‏هَزَّالُ لَوْ كُنْتَ سَتَرْتَهُ بِثَوْبِكَ كَانَ خَيْرًا مِمَّا صَنَعْتَ بِهِ\"\nهَزَّالُ ده كان هو إللي دفع ماعز وشجّعه إنه يروح لرسول الله ﷺ ويعترف باللي عمله ده،\nفرسول الله ﷺ بيعلّمه وبيعلّم الأمة كلها إن مادام محدش طلبه للشهادة خلاص، يبقى يسكت ويستر على صاحبه وميفضحوش\nوبعد موقف رجم ماعز ده، رسول الله ﷺ عارف إن الناس مش هتسكت، وفي كلام كتير هيتقال عنه،\nوفعلا الناس اختلفوا بعد رجم ماعز، فريق قال :\nده كده هَلك وأحاطت به خطيئته، \nوفريق تاني قال:\nمفيش توبة أفضل من توبة ماعز، ده جاء لرسول الله ﷺ ووضع إيده في إيد رسول الله ﷺ وقاله اقتلني بالحجارة\nورسول الله ﷺ كان عارف إن في ناس سواء في عصر الصحابة أو في العصور إللي بعد كده ممكن يُشفقوا على ماعز إنه إزاي يموت الموتة الصعبة دي،\nوممكن كان حد يقترح عدم إقامة الحدِّ على ماعز مادام أعلن توبته وجاء نادمًا\n☆وبالمناسبة هنا في سؤال:\nإيه لازمة الحد مادام ماعز خلاص أعلن توبته\nوهو احنا هنعرف صدق التوبة من كذبها إزاي والتوبة دي عمل قلبي بين العبد وربه؟\nلو كان بينه وبين نفسه خلاص مكنش ييجي بقى للإمام أو الحاكم ويقوله على إللي عمله،\nلكن هو جاء وظهر فعله باعترافه او بالبيّنة خلاص يقام عليه الحد،\nولو لم يُقَمِ الحدُّ عند ثبوت الجريمة بحجة توبة الفاعل؛ كده أي مجرم هيعمل إللي هو عايزه وبعدين يقول أنا تبت\nلكن وجود الحد هيمنع انتشار الفاحشة، والواحد هيفكر ألف مرة قبل ما يعمل حاجة زي كده\nفي نفس اليوم بقى إللي رُجم فيه ماعز لما جاء الليل رسول الله ﷺ قام خطب في الناس خطبة قال فيها:\n‏أَوَ كُلَّمَا انْطَلَقْنَا غُزَاةً فِي سَبِيلِ اللهِ تَخَلَّفَ رَجُلٌ فِي عِيَالِنَا لَهُ نَبِيبٌ كَنَبِيبِ ‏التَّيْسِ!\nعَلَيَّ أَنْ لَا أُوتَى بِرَجُلٍ فَعَلَ ذَلِكَ إِلَّا‏ ‏نَكَّلْت ‏‏بِهِ\"\nرسول الله ﷺ هنا بينبَّه الناس وبيقولهم متخلوش الموقف المأساوي إللي تعرَّض له ماعز لما رُجِمَ يخليكوا تنسوا  الجريمة إللي حصلت\nماعز اعتدى على حرمة امرأة، واعتدى على حرمة البيت إللي هي خرجت منه، واعتدى على حُرمَة زوجها أو أبيها أو أخيها، واعتدى على حرمة المجتمع.. فاللي حصل ده فاحشة مبيِّنَة\nده غير إن بسبب الجريمة دي ممكن يبقى في طفل بريئ\nهيفضل طول عمره متعذب وهيبقى معروف بين الكل إنه ابن زنا وممكن يُعيَّر بكده ليل نهار،\nفلا يرفع رأسًا، ولا يطلب عزًّا، مع أنه معملش حاجة وكل ذنبه إنه ابن زنا\nومش هقولكم بقى على المآسي الموجودة في مجتمعنا دلوقتي، وكمية الأطفال إللي الناس بيلاقوها في الشوراع وفي مقالب الزبالة وحاجة كده توجع القلب\nفرسول الله ﷺ هنا بيطلب من الناس إنهم\n 《يَحْكُموا عواطفهم》 بعقولهم، فهو بيصَوّر لهم موقف لا تطيقه نفس بشرية، إزاي\nيعني بيقولهم احنا بنخرج في عمل نبيل شريف وهو الجهاد في سبيل الله، عشان ندافع عن حقوق الشعب بكامله، ونحرص على كرامة الأمة بكاملها، \nفنلاقي ناس غدروا بينا، و مقدّروش حرمة بيوتنا فانتهزوا فرصة غيابنا، وسَطَوْا على أعزِّ ما نملك وهو شرفنا، واعتدَوْا على نسائنا،\nو يشير رسول الله ﷺ في كلامه :\n 《لَهُ نَبِيبٌ كَنَبِيبِ ‏التَّيْسِ》\nيعني إن إللي يعمل الجريمة دي تجرَّد في لحظة الفعل من كل مشاعر الإنسانية، وبقى يشبه الحيوانات فلا تأخذكم به رأفة\nوفي آخر كلامه رسول الله ﷺ بيُعلن في منتهى الصرامة إن لو حد جاله بعد ما وقع في في الفعل ده؛ هيكون عقابه هو نفس العقاب بدون أي تهاون\nلأن ده مش حقُّ رسول الله ﷺ الشخصي عشان يُفَرِّط فيه، أو يتنازل عنه، ده حقُّ لله عز وجل أولًا، وحقُّ المجتمع والشعب ثانيًا،\nفهو بيُعلن أمام الكل إن الحدَّ قد أُقيم رحمة بالمجتمع، ورحمة بالإنسانية، ولم يكن الغرض منه قسوة بإنسان، أو تشهيرًا بمذنب\n☆هقول لكم قصة بقى من الواقع بتاعنا\nواحدة زوجها مسافر وسايبها لوحدها، فوقعت في الزنا وحملت، \nفراحت للدكتورة عشان تعملها عملية إجهاض، والدكتورة عارفاها وعارفة إن زوجها مسافر، \nفالدكتورة نصحتها وإن إللي عملته ده حرام، والدكتورة رفضت طبعا تعملها عملية إجهاض،\nفقعدت تلف على الدكاترة على أمل إن حد يعملها العملية، والله أعلم أسقطت الجنين إزاي بعد كده،\nلكن المصيبة إن الموضوع اتكرر أكثر من مرة\nيعني كل فترة المرأة دي تيجي للدكتورة عشان تعملها إجهاض، لحد ما الدكتورة نفسها اتخنقت منها وكانت عايزة تقول لأهلها،\nفتخيلوا بقى الموقف، زنا وإزهاق نفس بغير حق أكتر من مرة\nقصة تانية لواحدة متزوجة برده وزنت مع جارهم أربع مرات والكلام ده هي إللي قالته بلسانها، \nوغيرها وغيرها من المآسي ربنا يعافينا ويعافي المسلمين،\nفتخيلوا لما الزوج ولّا الأب يكون بيشتغل وتعبان عشان راحة أهل بيته وفي الآخر زوجته ولّا بنته لا تحفظه في عرضه بسبب واحد خائن لا يُراعي حرمات الله\nشوفتوا إزاي جريمة الزنا مُخرّبة للبيوت وبيحصل بسببها اختلاط في الأنساب\nعشان كده وقوع أشد العقاب بأصحاب الجريمة دي يردع أصحاب الأهواء، \nوكمان هو عذاب للمفسدين في الأرض المُخربين السّاعين في الناس بالخطيئة والفساد\nصلى رسول الله ﷺ على ماعز صلاة الجنازة، لكنه لم يصلِّ عليه بعد ما رُجم مباشرة؛ صلى عليه في اليوم التالي على الرأي الراجح من أقوال العلماء،\nموضوع ماعز عدّى عليه يومين تلاتة كده والناس لسه مختلفين فيه زي ما قلنا من شوية،\nواحد بيقول هلك وأحاطت به خطيئته، والتاني يقول تاب توبة محدش تابها،\nبعدها جاء رسول الله ﷺ والناس قاعدين فسلَّم، ثمَّ جلس فقال: \n\"اسْتَغْفِرُوا ‏ ‏لِمَاعِزِ بْنِ مَالِكٍ\"\n ‏فقالوا: غفر الله ‏لماعز بن مالك\nفقال رسول الله ﷺ :‏ ‏\"لَقَدْ تَابَ تَوْبَة لَوْ قُسِمَتْ بَيْنَ أُمَّةٍ لَوَسِعَتْهُمْ\"\nيعني هو كان صادق في توبته إللي تابها دي، لدرجة إنه توبته تساوي توبة أمة بحالها،\nيعني بيقول من باب المبالغة، وإلا فالتوبة لا تُقسّم ولا تُجزّأ \nفهو بيوصف لهم أد إيه كانت توبة عظيمة، وده مع إن رسول الله ﷺ كاره بشدة للمعصية إللي حصلت دي،\nوكمان مع نَهْيِه المستمرِّ للناس عن إنهم يعملوا زي ما عمل  ماعز، ومع تحذيره من تكرار الأمر،\nفمع كل ده لا يتردَّد ﷺ في إنه يُعلن أمام الناس كلهم إن ربنا غفر لماعز خطيئته\nو لا يتردَّد إنه يطلب من الناس أن يستغفروا له! \nفلا يحقُّ للناس إنهم يخوضوا في عِرضه ما دام \n《أُقيم عليه الحدُّ》 خلاص، وما دام 《أعلن توبته أمام الجميع》وخصوصا إن الحدود بتُكفّر الذنب يَقِينا، \nيعني لو واحد شرب خمر، أو زنى أو سرق مثلا و أُقيم عليه الحد خلاص كده اتشالت من صحيفته المعصية الكبيرة إللي عملها دي،\nوالدليل قول رسول الله ﷺ:\n\" مَنْ فَعَلَ شَيْئًا مِنْ ذَلِكَ فَعُوقِبَ بِهِ فِي الدُّنْيَا فَهُوَ كَفَّارَته\"\nبعكس لو لم يُقُم عليه الحد وتاب بينه وبين ربنا، مش بيبقى عارف هل توبته توبة نصوح واتقبلت ولّا لأ،\nفاحنا هنا يا جماعة بنتكلم عن اليقين في معرفة الذنب اتغفر ولّا لأ عشان بس محدش يفهم كلامي غلط\nفماعز بن مالك لما تاب وأخد جزاء معصيته في الدنيا، ربنا تاب عليه ورسول الله ﷺ أمر الناس إنهم يدعوا له،\nورسول الله ﷺ مكنش خايف إنه لما يفتح المجال قصاد الناس بإنهم يدعوا لماعز بالمغفرة إنه كده بيجرّأهم على الذنب، على أساس بقى إن ربنا غفور رحيم وفي حد هيدعيلهم لما يموتوا\nلأ، لأن كده كده العقاب موجود والحدّ لم يُرفع ومازال موجود وبيتنفذ على كل واحد تسَوَّل له نفسه الاعتداء على حرمات الآخرين\nوده عكس إللي بيحصل في واقعنا الحاضر \nواحد ظلم وقتل واعتدى، ولم يعلن عن توبته قصاد الكل زي ما ماعز بن مالك عمل كده، ومات،\nفتقوم الناس تقعد تدعيله بقى بالرحمة والمغفرة وفسيح الجنات ويجهروا بكده ويشجعوا بعض على كده\nطيب ما هو يا جماعة احنا كده بنوصل رسالة لكل ظالم وفاسق وفاجر ومعتدي أيا كان هو مين وبنقوله:\n عيش انت بس اقتل وعذّب واظلم وانتهك حرمات الله ومتخفش في الآخر هنسامحك وندعيلك كمان\nفاحنا كده بنجرأ الظالم على الظلم بزيادة، و بنجرّأ مرتكب الكبائر إنه يستمر في عصيانه من غير ما نحس\nومتنسوش إن مَنْ أَمِن العقوبة أساء الأدب، واحد عارف إنه مهما ظلم وقتل وسرق وعصى وتجبّر محدش هيحاسبه في الدنيا،\nفخلاص بقى هيعمل ما بدا له وتشيع الفواحش والسرقة والظلم والقتل بين الناس،\nزي ماهو حاصل في زماننا دلوقتي بالضبط والله\nوانتم شايفين الواقع عامل إزاي\nبعد ما حصلت قصة ماعز بن مالك رضي الله عنه بفترة جاءت امرأة لرسول الله ﷺ يُقال لها الغامدية و قالت له:\n يا رَسولَ اللهِ، إنِّي قدْ زَنَيْتُ فَطَهِّرْنِي.\nفردّها رسول الله ﷺ زي ما عمل مع ماعز كده يمكن تراجع نفسها وتتوب بينها وبين ربنا، فلما جاء اليوم التالي جاءت لرسول الله ﷺ وقالت له:\n \"يا رَسولَ اللهِ، لِمَ تَرُدُّنِي؟ لَعَلَّكَ أَنْ تَرُدَّنِي كما رَدَدْتَ مَاعِزًا، فَوَاللَّهِ إنِّي لَحُبْلَى\"\nيعني انت بترجعني ليه يا رسول الله، انت عايز تعمل معايا زي ما عملت مع ماعز وتقولي استغفري وتوبي أو ممكن الموضوع يكون في شك،\nلا يا رسول أنا وقعت في الزنا وأنا دلوقتي حملت من الزنا ده فطهرني، وهي كانت مُحصَنَة هي كمان،\nفكده الحد بتاعها هو الرجم زي ماعز، لكن دي لو اترجمت دلوقتي الجنين إللي في بطنها هيموت وهو ملوش ذنب يُقتل\nطيب إزاي بقى هيقيم عليها الحد زي ما هي عايزة\nفقالَ لها رسول الله ﷺ:\nإمَّا لا فَاذْهَبِي حتَّى تَلِدِي\nيعني لو الموضوع زي ما بتقولي كده فارجعي لحد ما تولدي،\nيعني هتقعد باقي التسع شهور بتاعة الحمل وسط الناس وهي معروف عنها إنها زانية باعترافها هي تخيلوا\nو فعلا كملت التسع شهور وولدت وجاءت بالطفل الصغير ملفوف في قماشة لرسول الله ﷺ،\nوخلال الفترة دي محدش عايِرها ولا أذاها ولا أي حاجة خالص، سبحان الله عالمجتمع إللي كانت عايشة فيه بجد\nمع إنه مجتمع كان فيه أخطاء بس التعامل بينهم كان راقي جدا،\nومجرد ما الواحد فيهم يعرف إنه أخطأ في حق نفسه أو حق أخوه المسلم كان بيرجع على طول للصح ويتوب، مش يقعد يكابر ويجادل\nفلما جاءت لرسول الله ﷺ بالرضيع قالت له:\n\"هذا قدْ وَلَدْتُهُ\"\nيعني أنا خلاص ولدته أهه فطهرني بقى وأقم عليّ الحد، إللي هو بأي عقل الواحد يستوعب الكلام ده يا جماعة،\nتيجي لرسول الله ﷺ بعد حمل وولادة وتعبهم عشان تُقتل\nوهي إللي جاءت برجلها، يعني رسول الله ﷺ مكنش حاطط عليها حارس مثلا ولا راح بعتلها يشوفها ولدت ولّا لأ،\nبكامل إرادتها جت\nرسول الله ﷺ قالها: \"اذْهَبِي فأرْضِعِيهِ حتَّى تَفْطِمِيهِ\"\nبيقولها روحي وتعالي كمان سنتين بعد ما تفطمي الطفل الرضيع ده،\nهي لو أخدت ابنها وهربت رسول الله ﷺ مش هيعرف يجيبها أصلا\nلكن هي بتتعامل مع ربنا إللي شايفاها وعارفة إنها هتقابله في يوم من الأيام\nوالمرأة ترجع لبيتها وتفضل مع رضيعها لحد ما تفطمه ويكبر، وبعد السنتين تروح لرسول الله ﷺ بالصَّبِيِّ في يَدِهِ كِسْرَةُ خُبْزٍ وبقى خلاص متعود على أكل الطعام، كل ده عشان يقام عليها الحد،\nفَدَفَعَ رسول الله ﷺ الصَّبِيَّ إلى رَجُلٍ مِنَ المُسْلِمِينَ عشان يرعاه،\nوأمر الناس يحفروا لها حفرة إلى صدرها ووضعوها فيها وأمر رسول الله ﷺ الناس برجمها،\nوكان من إللي رجموها خالد بن الوليد رضي الله عنه، فلما رماها بحجر جاء الحجر في رأسها\" فَتَنَضَّحَ الدَّمُ علَى وَجْهِ خَالِدٍ فَسَبَّهَا\"\nيعني دم المرأة الغامدية طرطش على وجه خالد فراح خالد شاتمها،\nفَسَمِعَ رسول الله ﷺ سَبَّهُ إيَّاهَا، فَقالَ: \n\"مَهْلًا يا خَالِدُ، لقد تابت توبةً لو قُسِّمَتْ بين سبعين من أهلِ المدينةِ لوَسِعَتْهم، و هل وجَدَتْ توبةً أفضلَ من أن جادَتْ بنفسِها للهِ\"\nيعني رسول الله ﷺ لما سمع شتيمة خالد للمرأة قاله متشتمهاش دي تابت توبة تكفي سبعين من أهل المدينة، دي قدمت روحها لله\nوالمرأة الغامدية دي أمرها عجيب فعلا، إصرارها على التوبة وإن يُقام عليها الحد بعد أكتر من سنتين وتسيب طفلها، وتقتل بالطريقة الصعبة دي،\nفعلا صدق في التوبة ملوش مثيل\nطبعا مفيش أي دليل بيقول إن المرأة إللى زنى بها ماعز هي الغامدية، دي حالة ودي حالة تانية، فالله أعلم.\nوبعد كده صلى عليها رسول الله ﷺ ودُفِنَت، وقصتها وقصة ماعز رضي الله عنه بتُروَى لحد دلوقتي وإلى يوم الدين\nفزي مانتم شوفتوا كده، الصحابة وقعوا في الكبائر والصغائر ولكنهم كانوا يسارعوا في التوبة، ومكنش بيبقى في أي حاجة تهمهم غير رضى ربنا عنهم،\nوعندهم استعداد يضحوا بأي حاجة في مقابل الرضا ده، \nودي من الأسباب إللي جعلتهم مختلفين عن غيرهم وأفضل الخلق بعد الأنبياء، \nرضي الله عنهم أجمعين وجمعنا بهم مع رسول الله ﷺ في الفردوس الأعلى \nإن شاء الله المرة الجاية هنكمل الكلام عن باقي أحداث السنة التاسعة من الهجرة"}, {"n": 213, "l": "الجزء 187 | احداث السنه التاسعه من الهجرة | عروه بن مسعود الثقافي", "u": "", "t": "رابط تفسير القرآن كامل ف الكومنتات \n#قصص_الأنبياء(٢)\n#السيرة_النبوية\n#الحلقة_مائة_وسبعة_وثمانون\n#أحداث_السنة_التاسعة_من_الهجرة\n#عروة_بن_مسعود_الثقفي_ومؤمن_آل_ياسين\nهنكمل كلام عن أحداث السنة التاسعة من الهجرة إن شاء الله،\nفي شهر صفر من السنة التاسعة للهجرة أرسل رسول الله ﷺ الصحابي عبد الله بن عَوْسَجَة رضي الله عنه لبني حارثة بن عمرو يدعوهم إلى الإسلام،\nوكان رسول الله ﷺ كتب لهم صحيفة يدعوهم فيها للإسلام،\nوكانت الصحائف إللي بيتكتب عليها من الجلود، فلما أعطاهم رسالة رسول الله ﷺ أخذوا الصحيفة وغسلوها ورقّعوا بها أسفل دَلْوُهِم، يعني الدّلو إللي بيشيلوا بيه المية كان بينقط راحوا واخدين صحيفة رسول الله ﷺ وغسلوها من الكتابة ووضعوها في قعر الدلو، \nوطبعوا رفضوا الدخول في الإسلام، يُقال إن رسول الله ﷺ لما عرف قال: \n\"مالهم أذهب الله عقولهم!\"\nيعني رسول الله ﷺ دعا عليهم بذهاب العقل، لكن الله أعلم هل الكلام ده صحيح ولّا لأ\nلأن الحديث إللي ذُكر فيه دعاء رسول الله ﷺ عليهم ملوش إسناد، لكن أهل السِّير بيقولوه من باب الحكاية بس\nفي نفس الشهر، شهر صفر بعث رسول الله ﷺ قطبةَ بن عامر ومعاه عشرين رجل لحَيٍّ مِنْ خَثْعَمَ بالقرب من تَبَالة الموجودة بقرب منطقة عَسِير في الجزيرة العربية،\nولو تفتكروا قطبةَ بن عامر ده كان واحد من الستة من قبيلة الخزرج إللي أسلموا في البداية خالص لما كان رسول الله بيعرض الإسلام على القبائل، \nوبعد كده رجعوا ليثرب وبداوا يدعوا قومهم الخزرج وبدأوا يدعوا الأوس وبعد كده حصلت بيعة العقبة الأولى،\nوممكن ترجعوا للجزء الأربعين لو حابين تفتكروا الأحداث\nالمهم، رسول الله ﷺ بعثه للحي ده من خثعم وأمره إنه يُغِير عليهم،\nوكانت قبيلة خثعم تشرك بالله وتعبد صنم اسمه ذو الخُلّصَة وكان له اسم تاني هو الكعبة اليَمَانِية،\nالعشرين رجل من الصحابة كانوا بيتناوبوا على عشرة من الإبل،\nوهمّ ماشيين في الطريق وكانوا قرّبوا من القبيلة، شافهم رجل فمسكوه وبدأوا يسألوه لو عنده معلومات والرجل ده مش راضي يرد عليهم ولا يجاوبهم بحاجة،\nوبدأ ينادي بصوت عالي على القبيلة ويحذّرهم من المسلمون،\nفقتله المسلمون،\nوهجم المسلمون على القبيلة وحصل بينهم قتال شديد أدّى إلى كثرة الجرحى بين الفريقين،\nوقَتل قطبةُ بن عامر مَنْ قَتَلَ، وَسَاقُوا الأنعام وَالنساءَ وَالشَّاءَ إِلَى المدينَةِ.\nفي شهر ربيع الأول جاء رجل ليسلم عند رسول الله ﷺ، والرجل ده محدش كان يتوقع إسلامه أصلا\nالرجل ده هو 《عُروة بن مسعود الثقفي》\nوعروة بن مسعود ده هو تاني أعظم رجل عند العرب،\nفاكرين في الجزء الخامس عشر لما رسول الله ﷺ بدأ يدعوا قريش في البداية خالص وقالوا الكلام حلو بس ليه نزل على واحد فقير ضعيف زي محمد ﷺ،\nوقالوا لو كان أُنزل على رجل من القريتين عظيم كان يبقى أحسن،\n\"وَقَالُوا لَوْلا نُزِّلَ هَذَا الْقُرْآنُ عَلَى رَجُلٍ مِنَ الْقَرْيَتَيْنِ عَظِيمٍ\"\nوالمقصود بالقريتين هما مكة والطائف، الوليد بن المغيرة من مكة وعروة بن مسعود الثقفي في الطائف،\nوهو أشبه الناس بعيسى بن مريم، \nوعروة بن مسعود هو صاحب الحوار المشهور إللي حكينا عنه في صلح الحديبية وهو إللي قال:\nلقد وَفدتُّ على كسرى وقيصر والنجاشي، فوالله ما رأيت ملكاً قط يُعظّمه أصحابه، مثل ما يعظم أصحاب محمدٍ محمدًا!\nعروة بن مسعود مكنش موجود في الطائف لما رسول الله ﷺ حاصرها،\nلكنه كان في الأردن ساعتها بيتعلم صناعة الدبابات والمنجنيق،\nو هو راجع من الأردن عرف الأحداث إللي حصلت وإن رسول الله ﷺ فتح مكة وحاصر الطائف، فبعد ما عرف الأحداث دي كلها وقع الإسلام في قلبه،\nفبدل ما يروح الطائف راح مُتجه للمدينة لرسول الله ﷺ وأسلم عنده، وطبعا مش هقول لكم على فرح رسول الله ﷺ بإسلامه\nزعيم الطائف وعظيم العرب يدخل في الإسلام \nقعد عروة بن مسعود في المدينة فترة قصيرة وبعدين استأذن رسول الله ﷺ إنه يرجع لقومه في الطائف ليدعوهم للإسلام،\nفرسول الله ﷺ خاف عليه من أهل الطائف إنهم يقتلوه، فقال له رسول الله ﷺ :\"إنّهم إذًا قاتلوك\"\nفقال عروة لرسول الله ﷺ إن قومه بيحبوه ومستحيل يؤذوه وبيسمعوا كلامه، فمع إصراره أَذِن له رسول الله ﷺ إنه يروح يدعو قومه،\nو فعلا توجه عروة للطائف، ولما وصل ودخل بيته الناس بقت تجيله وتسلم عليه، فقال لهم دي تحية الجاهلية، وعليكم بتحية أهل الجنة السلام،\nفآذوه ونالوا منه و هو اتعامل معاهم بمنتهى الحِلم والصبر، وخرجوا من عنده وقعدوا يتآمروا عليه، ولما طلع الفجر طلع  على غُرْفة له فأذّن بالصلاة،\nفخرجت إليه ثقيف من كلّ ناحية، وبدأوا يعترضوا عليه وراح واحد منهم من بني مالك راميه بسهم في أَكحُله، والأكْحَلِ: هو العِرقُ الَّذي في نِهايةِ القدَمِ، \nوهو نفس المكان إللي أُصيب فيه سعد بن معاذ رضي الله عنه يوم الخندق، وكان رسول الله ﷺ كواه لسعد بالنار مرتين عشان النزيف يقف،\nفعروة لما أُصيب، استمر الدم ينزف من الجرح، فكده خلاص عرف إنه ميت ميت\nوقيل لعروة: ما ترى في دمك؟\nلأن في مجموعة لبست السلاح وقالوا إما نموت كلنا أو نقتل عشرة من سادات بني مالك،\nفنهاهم عروة عن القتال بينهم وقال: كرامة أكرمني الله بها، وشهادة ساقها الله إليَّ\nوقال لأصحابه:\nإذا متّ فادْفنوني مع الشهداء الذين قُتلوا مع رسول الله ﷺ، قبل أن يرتحل عنكم\"\nوعروة بن مسعود شهيد لأنه قُتل في موضع دعوة إلى الله،\nولما مات دفنوه مع أصحاب رسول الله ﷺ إللي قتلوا قبل ما رسول الله ﷺ يفك الحصار ويرجع للمدينة،\nرحمه الله ورضي الله عنه، \nفي حديث 《《ضعيف》 》بيقول إن رسول الله ﷺ لما وصله الخبر مقتل عروة بن مسعود قال:\n\"مَثَلُ عُرْوَةَ، مَثَلُ صَاحِب يَاسِينَ دَعَا قوْمَه إلَى الله فَقَتَلُوهُ\"\nهو الحديث وإن كان ضعيف لكن معنها صحيح، وهو إن قصة عروة بن مسعود تشبه قصة صاحب ياسين،\nأو مؤمن آل ياسين\nخلونا نشوف قصته وانتم احكموا بنفسكم هل فعلا في شبه بينهم هم الاتنين ولّا لأ\nكان في قرية كل أهلها بيعبدوا الأصنام، فربنا أرسل إليهم رسولين من عنده عشان ينذروا أهل القرية ويأمروهم بعبادة الله وحده،\n\"وَاضْرِبْ لَهُمْ مَثَلًا أَصْحَابَ الْقَرْيَةِ إِذْ جَاءَهَا الْمُرْسَلُونَ\"\nوطبعا كعادة أصحاب الباطل وزي ما شوفنا قبل كده في قصص الأنبياء أهل القرية كذبوا الرسولين دول،\nوتكذيبهم للرسل كان سريع، ربنا بيقول في الآية: 《فَكَذَّبُوهُمَا》 فاء التعقيب السريعة دي يعني مش عايزين نسمع أصلا، ولا كانوا عايزين يتفكروا في الأيات ويتدبروا، قابلوا الرسالة بالتكذيب مباشرة،\nفمن حِلم ربنا عليهم إنه أرسل مع الرسولين رسول ثالث،\nمع إن رسول واحد كفاية وخلاص قامت عليهم الحُجة ومادام كذبوا كان ممكن يهلكهم زي ما أهلك إللي كانوا قبلهم،\nلكن ربنا أرسلنا إليهم اثنين وكمان أرسل رسول ثالث يدعمهم ويقوّيهم وعشان يقيم عليهم الحُجة بزيادة ، زي ما بنقول كده زيادة تأكيد\n فقال الرسل الثلاثة لأهل القرية إن ربنا أرسلهم عشان ينذروهم عذاب ربنا وبطشه، وإنهم يجب عليهم عبادته وحده،\n\"إِذْ أَرْسَلْنَا إِلَيْهِمُ اثْنَيْنِ فَكَذَّبُوهُمَا فَعَزَّزْنَا بِثَالِثٍ فَقَالُوا إِنَّا إِلَيْكُمْ مُرْسَلُونَ\"\nفرد أهل القرية عليهم بإيه بقى\n\"قَالُوا مَا أَنْتُمْ إِلَّا بَشَرٌ مِثْلُنَا وَمَا أَنْزَلَ الرَّحْمَنُ مِنْ شَيْءٍ إِنْ أَنْتُمْ إِلَّا تَكْذِبُونَ\"\nهمّ في الأول كذبوا بس، لكن لما جاء الرسول الثالث وبقى لكلامهم أثر، بدأوا يعترضوا ويصدوا عن سبيل الله ويقولوا الشبهات،\nفقالوا نفس الكلام إللي أقوام الرسل إللي قبل كده قالوه\nقوم نوح وصالح وشعيب قالوا نفس الكلمة، اعتراضهم على أنبيائهم مفيهوش أي دليل وبراهين قوية،\nلمجرد إن الكلام مش منطقي بالنسبة لهم فيقوموا مكذبينه،\nفهم شايفين إن مش من المنطق إن ربنا يرسل رسول في هيئة بشر، فخلاص يبقى كده الرسل دول كاذبين\nهل كونهم بشر يمنع إن ربنا يؤتيهم العلمً والحُجة؟\n هل كونهم بشر يعني إننا لا نطيعهم؟ \nهل كونهم بشر يعني بأنهم غير صادقين؟ \nكلامهم مجرد أعذار عشان يبرروا لنفسهم تكذيب الرسل وعدم اتباعهم\nلا وبيقولوا إيه خدوا بالكم: \n\"مَا أَنْزَلَ 《الرَّحْمَنُ》 مِنْ شَيْءٍ\"\nيعني كأنهم بيقولوا للناس المستضعفين احنا مؤمنين أصلا بالله، مؤمنين بالرحمن ولكن هؤلاء -على الرسل يعني- لم يرسلهم الرحمن والرحمن لم ينزل أي شيء،\nودايما الطغاة وكبار المجرمين بيتكلموا لما بيخافوا إن الضعفاء هيروحوا منهم،\nما هو لو مفيش ضعفاء كده ملكهم هيزول، فلازم يشوّهوا صورة الداعي للخير،\nوكمان انتم جايين تخوّفونا من العذاب والعقاب من ربنا الرحمن\nلا لا الرحمن لم يأمر بشيء ولم ينهَ عن شيء، انتم إللي بتفتروا  وتكذبوا على ربنا، وإللي بتقولوه ده ضد رحمة ربنا\nزي جماعتنا إللي مهما نحاول نفهمهم إن ربنا شديد العقاب ولا يظلم مثقال ذرة وفي عقاب وحساب وفي نار وفي عذاب، ولازم نسمع كلامه ونبعد عن إللي نهى عنه،\nيقولوا ده ربنا غفور رحيم وانتم إللي معقدين الدنيا والجنة والنار مش بإيدكم عشان تقولوا مين إللي هيدخل الجنة ومين إللي هيدخل النار وبطلوا تشدد \n☆وهنا في نقطة محتاجين نعرفها ونفهمها كويس وهي إن الرحمة من كمال العدل، يعني من كمال رحمة الله إنه يرحم المُطيع ومن كمال رحمته أن يعذّب العاصي،\nمش الواحد يعيش يعمل ما بدا له وربنا ميحاسبهوش، دي مسمهاش رحمة دي اسمها عبث والعياذ بالله\nمفيش تساوي أبدا بين المطيع والعاصي، \nوربنا نفسه قال:\n\"أَمْ حَسِبَ الَّذِينَ اجْتَرَحُوا السَّيِّئَاتِ أَنْ نَجْعَلَهُمْ كَالَّذِينَ آمَنُوا وَعَمِلُوا الصَّالِحَاتِ سَوَاءً مَحْيَاهُمْ وَمَمَاتُهُمْ سَاءَ مَا يَحْكُمُونَ\"\nمستحيل يتساوى المُسِيئون المكثرون من الذنوب المقصرون في حقوق ربهم،\nبالطائعين إللي قاموا بحقوق ربهم، واجتنبوا إللي يُسخط ربنا ومستمرين في تقديم رضى ربنا على هوى أنفسهم،\n\"أَفَنَجْعَلُ الْمُسْلِمِينَ كَالْمُجْرِمِينَ*مَا لَكُمْ كَيْفَ تَحْكُمُونَ\"\nفأهل القرية قالوا لهم انتم بشر والرحمن منزّلش حاجة فبالتالي كل كلامكم كذب في كذب\nلا وبيتكلموا بثقة متناهية، كل كلامهم بالنفي والإستثناء \n《ما و إلا》\nالرّسل مطولوش معاهم كتير وقعدوا يدافعوا، همّ ردوا عليهم بكلمتين وبكل يقين، قالوا:\n\" قَالُوا رَبُّنَا يَعْلَمُ إِنَّا إِلَيْكُمْ لَمُرْسَلُونَ * وَمَا عَلَيْنَا إِلَّا الْبَلَاغُ الْمُبِينُ\"\nكفاية إن ربنا يعلم إننا مرسلون لكم واحنا فوضنا أمرنا لله وهو يعلم صدقنا واحنا عارفين إن ربنا هينصرنا ولن يتركنا،\nفكأنهم بيهددوهم :\nمش انتم بتقولوا اننا كذابين؛ طب شوفوا بقى ربنا هيعمل فيكم إيه\nوأصلا احنا مهمتنا و دورنا إننا نبلغكم ونوضح لكم الأمور وخلاص،\nوفعلا الرسل بدأوا يدعوا في الناس لحد ما دعوتهم مش بس وصلت لأهل القرية كلهم؛ لأ، ده دعوتهم وصلت لأقصى المدينة،\nفلما أهل القرية لقوا مفيش فايدة ومش لاقيين شُبه يقولوها،\nقالوا للرسل:\n\" قَالُوا إِنَّا تَطَيَّرْنَا بِكُمْ لَئِنْ لَمْ تَنْتَهُوا لَنَرْجُمَنَّكُمْ وَلَيَمَسَّنَّكُمْ مِنَّا عَذَابٌ أَلِيمٌ\"\nيعني انتم من ساعة ما جيتم ومفيش حاجة عِدلة حصلت، كل المصايب إللي بتحصل دي بسببكم\nومن سنة ربنا الكونية إنه لما بيرسل رسول لقوم ويكذبوه يبتليهم بشوية ابتلاءات كده عشان يديهم فرصة للرجوع،\nربنا بيقول:\n\"وَمَا أَرْسَلْنَا فِي قَرْيَةٍ مِنْ نَبِيٍّ إِلا أَخَذْنَا أَهْلَهَا بِالْبَأْسَاءِ وَالضَّرَّاءِ لَعَلَّهُمْ يَضَّرَّعُونَ\"\nفهمّ لما كذبوا الرسل ربنا ابتلاهم بالابتلاءات عشان يفوقوا ويعتبروا، فبدل ما يعتبروا بقى ويرجعوا لربنا ييجي كبار المجرمين ويقولوا للناس احنا كنا طول عمرنا عايشين كويس محصلش بلاء غير لما الناس دي جت،\nواحنا عشان نحافظ على البلد فاحنا هنعذبهم عشان يكونوا عبرة وبعدها نقتلهم لو مسِكتوش\nهل الرسل سكتوا بقى؟ لأ\n\" قَالُوا طَائِرُكُمْ مَعَكُمْ أَئِنْ ذُكِّرْتُمْ بَلْ أَنْتُمْ قَوْمٌ مُسْرِفُونَ\"\nيعني إللي بيحصل لكم ده بسبب ذنوبكم، ولو سيبتم القرية دي و روحتم مكان تاني الابتلاءات دي هتروح معاكم؛ لأنكم انتم السبب فيها\nثم احنا لما نيجي نكلمكم عن ربنا تقولوا ده الابتلاءات بسبب الدين، طب وقبل كده ما هو كان في ابتلاءات اشمعنا يعني جايين دلوقتي تقولوا إن احنا السبب والدين هو السبب\nلأ ده انتم إللي مسرفين على نفسكم بالمعاصي والذنوب وهو ده سبب الابتلاءات والعذاب إللي انتم فيه\nطبعا كده الصدام بين الطرفين اشتد وخلاص عايزين يقتلوا الرسل والطرفين وصلوا لحارة سد زي ما بنقول،\nفإيه إللي يحصل \nزي ما جاء رجل من أقصى المدينة يحذر موسى من الملأ إللي عايزين يقتلوه قبل الرسالة،\nوزي ما مؤمن آل فرعون دافع عن موسى لما الملأ كانوا عايزين يقتلوه هو ومن آمن معه،\nفي اللحظة دي لما الملأ قرروا يقتلوا الرسل:\n\"جَاءَ مِنْ أَقْصَى الْمَدِينَةِ رَجُلٌ يَسْعَى قَالَ يَا قَوْمِ اتَّبِعُوا الْمُرْسَلِينَ*اتَّبِعُوا مَنْ لَا يَسْأَلُكُمْ أَجْرًا وَهُمْ مُهْتَدُونَ * \nوَمَا لِيَ لَا أَعْبُدُ الَّذِي فَطَرَنِي وَإِلَيْهِ تُرْجَعُونَ * \nأَأَتَّخِذُ مِنْ دُونِهِ آلِهَةً إِنْ يُرِدْنِ الرَّحْمَنُ بِضُرٍّ لَا تُغْنِ عَنِّي شَفَاعَتُهُمْ شَيْئًا وَلَا يُنْقِذُونِ\"\nرسالة الرسل وصلت مش بس لكل القرية، دي وصلت لأقصى المدينة، والرجل مستناش الرسل يأتوه ده هو إللي جاءهم،\nوجاي بسرعة عشان يقول للناس اتبعوا المرسلين، ويدعوهم لعبادة الله وحده،\nإللي يشوف الموقف يستغرب، يعني انت جاي من أقصى المدينة عشان تقولهم اتبعوا المرسلين وتدعوهم باللي الرسل أصلا تعبوا من كتر ما بيكرروا الكلام ده معاهم؟\n طب انت جبت إيه جديد طيب\nثم يعني الرسل الثلاثة مقدروش يقنعوا أهل القرية بإنهم يؤمنوا بالله، انت لوحدك كده هتقدر تقنعهم؟\nلكن هو مكنش بيفكر كده، هو كان شايل هم الرسالة وتبليغ الدين، \nهو عايز يبذل أي حاجة ويحاول أي محاولة حتى لو كان غيره جرب قبل كده، لعل وعسى الناس تستجيب،\nوفي الآخر الناس مستجابتش،\nوقالهم: اسمعوني كويس أنا بقول لكم بكل وضوح أنا آمنت بربكم\n\"إِنِّي آمَنْتُ بِرَبِّكُمْ فَاسْمَعُونِ\"\nفقاموا عليه وقتلوه\nوده زي موقف عروة بن مسعود بالضبط\nرسول الله ﷺ حاصر الطائف ودعاهم للإسلام وشافوا معجزة هزيمتهم وحضور الملائكة في غزوة حنين،\nومع كل ده لم يؤمنوا،فجاء عروة وأسلم وقال إنه هيروح يدعوهم،\nوجاء من المدينة للطائف عشان يدعو قومه للإسلام، فكانت النتيجة موته،\nفالاتنين هنا ماتوا في موقف دعوة والاتنين شهداء عند ربنا، إللي يشوف ظاهر الموقف يقول طيب ما كان كل واحد يخليه في مكانه ويعيش بسلام وخلاص،\nلازم يعني يروحوا يرموا نفسهم في التهلكة دي\nللأسف الناس مش فاهمة إن دي مش تهلكة، عارفين لما الرجل ده مات حصل معاه إيه؟\n\"قِيلَ ادْخُلِ الْجَنَّةَ\"\nدخل الجنة على طول، لأنه شهيد والشهداء أحياء عند ربهم يرزقون،فقال الرجل:\n\"قَالَ يَا لَيْتَ قَوْمِي يَعْلَمُونَ * بِمَا غَفَرَ لِي رَبِّي وَجَعَلَنِي مِنَ الْمُكْرَمِينَ\"\nيعني ياريتهم يعرفوا إني كنت على حق وإن ربنا غفر لي وأدخلني الجنة،\nلكن قومه خلاص ربنا أهلكهم بالصيحة وهي صوت هائل عظيم، ماتوا بعدها \n\"إِنْ كَانَتْ إِلَّا صَيْحَةً وَاحِدَةً فَإِذَا هُمْ خَامِدُونَ\"\nوالقضية منتهتش لسه، تخيلوا حسرتهم، ندامتهم يوم القيامة لما يجتمع العذاب على الروح والبدن، خلاص ملهمش أي فرصة تانية،\nلكن احنا لسه عندنا فرصة للتوبة واتباع أوامر ربنا واجتناب نواهيه\nإن شاء الله المرة الجاية هنشوف واحد تاني من ثقيف برده كان على دين إبراهيم، وكان مستني ظهور نبي آخر الزمان،\nلكن لما ظهر......هنعرف عمل إيه المرة الجاية\n♡أنصحكم يا جماعة بسماع تفسير القرآن كامل للدكتور 《أحمد عبد المنعم》، هتلاقوا في التعليقات\n رابط لتفسير قصة مؤمن آل ياسين، اللهم بارك رائعة،\nوهو يتناول تفسير القرآن بطريقة مميزة جدا ويربط أحداث التفسير بالواقع وبأسلوب مميز وسهل وبسيط جدا بدون أي تعقيد وأكثر كلامه بالعامية"}, {"n": 214, "l": "الجزء 188 | احداث السنه التاسعه من الهجرة | اميه بن ابي الصلت", "u": "", "t": "#قصص_الأنبياء(٢)\n#السيرة_النبوية\n#الحلقة_مائة_وثمانية_وثمانون\n#أحداث_السنة_التاسعة_من_الهجرة\n#أمية_بن_أبي_الصلت_وبلعام_بن_باعور\nوقفنا المرة إللي فاتت عند قصة رجل من ثقيف كان من الموحدين المعدودين في شبة الجزيرة العربية، والموحدين ززي ما قلنا قبل كده مكنوش بيعبدوا الأصنام،\nالرجل ده اسمه أُميّة بن أبي الصّلْت، وأبوه كان واحد من زعماء ثقيف،\nولو تفتكروا واحنا بنتكلم في بداية السيرة قلنا إن كان في مجموعة من الموحدين مكنوش بيعبدوا الأصنام، \nوكان منهم زيد عمرو بن نفيل و ورقة بن نوفل واحنا اتكلمنا عنهم بالتفصيل قبل كده،\nوكان منهم كمان أمية بن أبي الصّلت ده، و أمية كان شاعر كبير من شعراء الجاهلية وكان يُكثر في شعره من وصف الجنة والنار والبعث وكان على علاقة بأهل الكتاب،\nو أمية مكنش موّحد وبس، ده كان داعية، يعني بيدعو الناس لترك عبادة الأصنام وعبادة ربنا وحده،\nو يُقال إن امية بن أبي الصلت هو إللي علم قريش يكتبوا《 باسمك اللهم 》 في بداية الكتابة،\n زي كده لما بنكتب بسم الله الرحمن الرحيم في بداية الرسائل والخطابات بتاعتنا\nوكان أمية عارف إن في نبي هيظهر في آخر الزمان، وكان أمية بيتمنى إنه يكون هو النبي ده،\nوحتى إنه يقال في بعض الأثار الضعيفة إن أمية كاد يكون نبي بسبب الحكمة إللي كانت عنده\nوقال بعض العلماء إن لولا ظهور رسول الله ﷺ كانت ثقيف قالت إن أمية نبي،\nطبعا حد بالمكانة والحكمة والعلم ده كله المتوقع منه إنه أول ما يسمع برسول الله ﷺ على طول يدخل في الإسلام ويكون من أول المدافعين عنه والمُناصرين له\nلكن ده محصلش\nأمية بن أبي صلت لما وصل له أخبار ظهور رسول الله ﷺ بعد حوالي ثمانِ سنوات من البعثة، راح وقعد معاه وسمع منه القرآن وسأله عن الدين،\nفقرأ رسول الله ﷺ عليه سورة يس،\nإللي بتحكي قصة أصحاب القرية وقصة مؤمن آل ياسين إللي اتكلمنا عنه المرة إللي فاتت،\nفعرف أمية إن رسول الله ﷺ هو نبي آخر الزمان، فترك رسول الله ﷺ ومشي بدون ما يدخل في الإسلام،\nفسأله أصحابه إللي كانوا معاه عن رسول الله ﷺ، فقال لهم إنه فعلا نبي آخر الزمان وإنه على الحق،\nلكن أمية كان في قلبه حقد وحسد على رسول الله ﷺ خلاه يرفض اتباع رسول الله ﷺ،\nو قعد يتجوّل في شبه الجزيرة العربية، ووصل له أخبار رسول الله ﷺ وانتصاره في بدر،\nوجاء لزيارة القَليب أو البئر إللي ألقى فيه رسول الله ﷺ المشركين بعد مقتلهم في غزوة بدر،\nوكان عتبة بن ربيعة وشيبة بن ربيعة من القتلى وهم أبناء خاله،\nفلما عرف بمقتلهم رَثاهم، يعني قال فيهم شعر حزين، زي كده لما حد بيموت وواحدة تقعد تندب على الميت ده\nوشقَّ هدومه وبكى وعقر ناقته زي ما بيصنع الجاهليون لما يموت لهم قريب،\nومكتفاش بكده ده بقى يُحرِّض المشركين على الثأر لهم وبكده انضم  لمعسكر الشرك والوثنية ضد الإسلام\nو رجع للطائف وقعد فيها واستمر على الكفر لحد ما مات سنة تسعة هجريا قبل إسلام أهل الطائف على الراجح من أقوال العلماء،\nرسول الله ﷺ قال عنه:\n\"إن كاد ليُسْلِمَ\"\nيعني كان قريب جدا من الإسلام، وشعره كله عن مبادئ الإسلام، لدرجة إن في ناس اتهمت رسول الله ﷺ إنه نقل القرآن من شعر أمية بن أبي الصلت\nوطبعا مش محتاجة أقول إن الكلام ده كذب، وإن القرآن هو كلام الله إللي أنزله على رسول الله ﷺ \nفي بعض أقوال العلماء بيقولوا إن نزلت في أمية بن أبي الصلت آية:\n\" وَاتْلُ عَلَيْهِمْ نَبَأَ الَّذِي آتَيْنَاهُ آيَاتِنَا فَانْسَلَخَ مِنْهَا فَأَتْبَعَهُ الشَّيْطَانُ فَكَانَ مِنَ الْغَاوِينَ* \nوَلَوْ شِئْنَا لَرَفَعْنَاهُ بِهَا وَلَٰكِنَّهُ أَخْلَدَ إِلَى الْأَرْضِ وَاتَّبَعَ هَوَاهُ ۚ فَمَثَلُهُ كَمَثَلِ الْكَلْبِ إِن تَحْمِلْ عَلَيْهِ يَلْهَثْ أَوْ تَتْرُكْهُ يَلْهَث ۚ \nذَّٰلِكَ مَثَلُ الْقَوْمِ الَّذِينَ كَذَّبُوا بِآيَاتِنَا ۚ فَاقْصُصِ الْقَصَصَ لَعَلَّهُمْ يَتَفَكَّرُونَ\"\nيعني ربنا أعطى أمية بن أبي الصّلت الحكمة والعلم، لكنه مع ذلك ترك كل ده واتبع الشيطان، و كان من الضالين عن سبيل الله\nوفي قول تاني وهو الراجح إن الآية دي نزلت في\n 《بَلْعَمُ بْنُ بَاعُورَاءَ أو بلعام بن باعور》وهنعرف قصته بعد شوية\n☆لو تاخدوا بالكم بقى هتلاقوا إن موقف أمية بن أبي الصلت ده عامل زي موقف إبليس مع آدم عليه السلام\nبمعنى إن أمية بن أبي الصلت حسد رسول الله ﷺ زي بالضبط كده إبليس لما حسد آدم عليه السلام\nفإبليس كان طائع لله وعنده علم وله مكانة،\nلكنه لما حسد آدم تكبر و عصى أمر ربنا وأصر على كده فكانت نهايته الخلود في النار،\nوأمية ربنا أعطاله الحكمة والعلم لكن بسبب الحسد إللي كان في قلبه وإنه مطلعش هو نبي آخر الزمان؛ فاختار الكفر على إنه يكون تابع لحد تاني، وبالتالي نهايته الخلود في النار،\nفي ناس كده بتشترط:\nأعبد ماشي مادام أنا النبي وأنا القائد ، وأنا إللي الناس هتتبعه، لكن لو مش أنا.. خلاص، مش هكون تابع\nوتلاقوا النوعية دي من الناس بيحصل منهم تصرفات عكسية، يعني بعد ما كان طائع عابد لله بيدافع عن دين الله تلاقيه بقى هو إللي بيحارب دين ربنا وبيضل الناس و يبعدهم عنه\nوربنا اختار لنا كلمة 《 انسلخ》 عشان يعرفنا أهمية العمل مع العلم، يعني العبرة مش بالعلم بس،\nاحنا بنتعلم عشان نعمل، إيه الفايدة لما أمية بن أبي الصلت يبقى عنده العلم لكنه لا يعمل بيه وينسلخ منه\nفالعمل بالنسبة للعلم زي الجلد بالنسبة للبشر كده، يعني إللي بيتعلم بدون ما يعمل بيبقى عامل زي المُنسلخ كده معندوش جلد،\nجسمه مُشوّه ..شكله وحش ..بيعاني من أزمات نفسية،\nفزي ما الجلد بيزين الجسد كذلك العمل هو إللي بيزين العلم\nفاللي بيذوق حلاوة الإيمان فترة معينة وبعدين يترك العمل بيعاني من أزمات نفسية؛ لأنه مش بيبقى عارف يبقى فاجر مع الفُجّار تماما ولا هو عارف يرجع لطريق ربنا\nفاللي يترك العمل بآيات الله ربنا شبّهه بالانسلاخ، وطبعا أول ما الشيطان يلاقي الإنسان بدأ يترك العمل يقوم مُتّبِعه على طول عشان يستعمله ويخليه جندي من جنوده،\nزي أمية بن أبي الصلت كده، أو زي بَلْعَمُ بْنُ بَاعُورَاءَ أو بَلعَام بن باعور\nوبلعام أو بلعم ده كان واحد من علماء بني إسرائيل،\nوقيل إنه كان من القوم الجبارين إللي كانوا ساكنين في بيت المقدس إللي موسى عليه السلام أخذ بني إسرائيل عشان يقاتلوهم وبنو إسرائيل رفضوا، واتكلمنا عنهم بالتفصيل قصص الأنبياء،\nالمهم، بلعام ده ربنا أعطاه آيات وعلّمه علوم كثيرة، و يقال إنه كان عنده اسم الله الأعظم، الذي إذا دعي به أجاب،\nيعني بلعام كان مستجاب الدعوة، أي حاجة يدعو بيها ربنا يستجيب له على طول،\nلكن كل العلم ده لم يفيده، قلبه كان فيه مرض حب الدنيا والرياء والسُّمعَة،\nقوم بَلعام كانوا عايزين يحاربوا نبي من الأنبياء، ويُقال إن النبي ده هو موسى عليه السلام، الله أعلم\nلكنهم كانوا خايفين، فقالوا لبلعام احنا عايزينك تدعي على نبي الله،\nطبعا هو في البداية اتخض وقالهم إزاي أدعو على نبي الله، ثم انتم عايزيني أدعي عليه ليه \nفقالوا له إنهم هيحاربوه، وعايزينه يبقى هو في مواجهة النبي، فيدعو عليه،\nفي البداية كان خايف ومتردد ومش مقتنع، لكنهم قعدوا يُغروه بالمال والرئاسة والمنصب، وهو ده إللي كان عايزه\nفوافق على طلبهم بإنه يدعي على النبي\nوهو عارف إنه نبي، وعارف إنه مُؤيد من الله، وعارف قدرة ربنا وإنه لن يضر أوليائه ومع ذلك رفع إيده للسماء ودعا على نبي الله في الزمن ده\nطبعا ربنا لم يستجب له، وكان لما ييجي يدعو بالشر على نبي الله كان لسانه يتحول ويقوم داعي على قومه، وعرف ساعتها إنه خسر الدنيا والآخرة ولم ينفعه علمه وانسلخ من الإيمان زي ما الثعبان بينسلخ وبيغير جلده،\nفبعد ما كان رجل مؤمن تقي؛ بقى فاجر كافر مجرم شقي\nربنا عقّب بقى على إللي عمله بلعام أو أمية بن أبي الصلت أو أي حد هيمشي على نفس منهجهم ويعمل زيهم، قال الله عز وجل:\n\" وَلَوْ شِئْنَا لَرَفَعْنَاهُ بِهَا وَلَٰكِنَّهُ أَخْلَدَ إِلَى الْأَرْضِ وَاتَّبَعَ هَوَاهُ ۚ فَمَثَلُهُ كَمَثَلِ الْكَلْبِ إِن تَحْمِلْ عَلَيْهِ يَلْهَثْ أَوْ تَتْرُكْهُ يَلْهَث\"\nيعني لو كان استمر على علمه و عمل باللي بالعلم إللي عنده واستمر على تقواه؛ كان ربنا رفع مكانته في الآخرة ولكنه رضي بالحياة الدنيا وباع آخرته الباقية بالدنيا الفانية،\nوبقى عبد لهواه وتابع له\nوبقى زيه زي الكلب إن تحمل عليه يلهث أو تتركه يلهث، لو الكلب واقف هتلاقيه بيلهث، لو بيجري برده هتلاقيه بيلهث، فهو في حالة لَهث دائم،\nفالشخصية دي سواء اتعلم أو متعلمش مفيش فرق في حياته، كده كده مش هيعمل بالآيات دي، \nوجمهور المفسرين قالوا إن ربنا ضرب المثل ده للشخص الذي لا يتأثر بمواعظ القرآن،\nيعني واحد تحمل عليه : تخوّفه بآيات الله وبالآخرة وبالعذاب لا يتأثر؛ ويظل يلهث في الشهوات،\nتبعد عنه متكلموش في حاجة برده بيلهث في الشهوات، \nزيه زي الكلب، واقف.. قاعد.. بيجري.. برده بيلهث،\nفالكلب في أصل خِلقته عنده مشكلة في التنفس عن باقي الحيوانات بتخليه يلهث كده، \nفالعلماء قالوا إن إللي بيبعد عن الوحي والعمل بيه كأنه حصل عنده تغيير في أصل خلقته يعني تغيير في الفطرة،\nوكلمة يلهث دي بتيجي مع العطشان، فالإنسان لا يشبع من الشهوات\nفطول ما الواحد بعيد عن الوحي هيفضل عطشان و مش هيشبع أبدا من الشهوات،\nفأي شهوة الإنسان بيعملها بيحس بمتعتها لفترة بسيطة وبعدين يرجع للعطش تاني ويبدأ يدوّر على شهوة جديدة،\nزي إللي بيحب يسمع أغاني مثلا،\nهتلاقيه بيستمتع بأغنية طول ما هي شغالة وبعد ما تخلص بيبقى عايز يسمعها تاني أو يسمع حاجة زيها وهكذا، \nودايرة مش بتخلص وقيسوا على كده، زي إللي بيشرب من الماء المالح مش هيشبع بالعكس هيزيد عطشه،\nفالحل بتاعه إنه يرجع للوحي مرة تانية، وزي ما ابن القيم قال إن القلب فيه فاقة يعني فيه فقر، ومش هيسد الفقر ده غير إن الإنسان يبقى عبد لله، \nومش بالعلم بس لازم علم وعمل، فالعلم مش بس هو إللي بيرفع صاحبه، إللي بيرفعه هو العمل بالعلم، ويكون العمل خالصا لوجه الله\nولو تاخدوا بالكم في الآية ربنا بيقول: \n《فَانْسَلَخَ》 《فَأَتْبَعَهُ》《 فَكَانَ》 مِنَ الْغَاوِينَ، الفاء دي بتدل على السرعة،\n يعني كل حاجة حصلت بسرعة، بعد ما كان من أهل الإيمان، على طول بقى من أهل الغِواية والضلال،\nفربنا بيحذرنا وبيقول لنا إن السقوط سهل،\nيعني الواحد عشان يوصل ويستقر في عبادة معينة بيكون جاهد نفسه فيها وتعب، \nزي إللي بيطلع السلم كده، بيتعب على ما يطلع، \nبعكس إللي بينزل السلم، \nبيكون نزوله سهل، فسهل إن الواحد يسيب العمل بالطاعات بسرعة وبيبقى مفكرها في البداية حاجات بسيطة و فجأة بيلاقي نفسه في أسفل سافلين للأسف، وعمره ما كان يتخيل إنه يوصل للوضع ده\n☆عارفين،\nكل واحد فينا كل يوم تقريبا بيتعرض لموقف بلعام أو موقف أمية بن الصلت، حاجات كتير اتعلمناها وبنتعلمها،\nومن إللي اتعلمناه ده في إللي لم نعمل بيه، وفي إللي عملنا بيه و توقفنا عن العمل بعد فترة،\nفي إللي عرفت إن النقاب فرض في زمن الفتنة على الأقل وملبستوش، وفي إللي لبسته وقلعته، والموضوع موقفش عند خلع النقاب، ده اتطور للبس بناطيل ومساحيق تجميل، ميكب أب يعني، \nفي إللي عرف إن الربا حرام ولسه بيتعامل بيه، وفي إللي كان توقف عن التعامل بالربا ورجع له تاني،\nوفي إللي عارف إن الأغاني والأفلام والمسلسلات حرام ومع ذلك مكمل عادي وبيتفرج،\nوفي إللي توقف ورجع تاني، وفي....وفي....وفي....\nحياتنا مليانة بالمواقف المشابهة لهم،\nعشان كده بتلاقوا ناس كتيييير بتقع حوالينا وحالها بيتغير تماما بعد ما كانوا في منزلة عالية وكان في منهم حتى ناس مشهورة وبنستغرب ليه حصل كده،\nو الإجابة عندنا في القرآن :\nآتيناه  آياتنا  فانسلخ  منها  فكان  من  الغاوين\nربنا يثبتنا وإياكم على الحق حتى نلقاه ولا يجعلنا من الغاوين"}, {"n": 215, "l": "الجزء 189 | احداث السنه التاسعه من الهجرة | إسلام عدي  بن حاتم", "u": "", "t": "#قصص_الأنبياء(٢)\n#السيرة_النبوية\n#الحلقة_مائة_وتسعة_وثمانون\n#أحداث_السنة_التاسعة_من_الهجرة\n#إسلام_عدي_بن_حاتم\nهنكمل أحداث السنة التاسعة من الهجرة إن شاء الله، \nواحنا كنا واقفين عند الأحداث في شهر ربيع الأول إللي كان أسلم فيه عروة بن مسعود الثقفي،\nفي شهر ربيع الأول برده رسول الله ﷺ جهّز سريّة عشان تروح وتدعو قبيلة القُرطاء من بني كلاب للإسلام، \nوكانت السرية دي من ضِمن بعوث رسول الله ﷺ لنشر التوحيد في الجزيرة العربية وما حولها بعد فتح مكة،\nاختار رسول الله ﷺ الصحابي الضَّحاك بن سفيان الكِلابي قائد للسرية لأنه من بني كلاب وهو أدرى الناس بيهم،\nوكان الضحاك بيُسمى سيّاف رسول الله ﷺ، و كان يساوي مائة فارس رضي الله عنه ،\nوكان معاه في السرية دي الأَصْيَد بن سلمة بن قُرط، فلما وصلت السرية وبدأوا يدعوهم للإسلام؛ بني كلاب رفضوا الإسلام وأصروا على القتال فقاتلهم المسلمون وهزموهم،\nوالأصيد بن سلمة قابل أبوه سلمة وكان راكب على فرس وكان كافر،\nفدعاه الأصيد للإسلام وأعطاه الأمان، فراح أبوه شتمه وشتم الإسلام \nفضرب الأصيد عرقوبي فرس أبيه، يعني ضرب قدم الفرس من الخلف،\nفلما وقع الفرس على عرقوبيه سند سلمة على رمحه ومسك فيه وجاءه رجل من المسلمين فقتله،\nوانهزمت القبيلة وقُتل بعض رجالها وأخذوا منهم غنائم ورجعوا للمدينة.\nو موقف الأصيد ده يعلمنا إن الولاء لدين الله يفوق صلات العشيرة والأهل\nفي نفس الشهر شهر ربيع الأول جاء مجموعة من الحبشة عشان يُغيروا على ساحل جدة على البحر الأحمر ويدخلوا  ديار المسلمين،\nفجهز رسول الله ﷺ سرية من ثلاثمائة صحابي وخلّى قائدهم الصحابي عَلقمة بن مُجَزّر المُدْلِجي،\nانطلقت السرية باتجاه الساحل ولما وصل الجيش ودخلوا  المياه متجهين نحو الأحباش، هرب الاحباش أصحاب الغارة من الصاحبة وراحوا راجعين لبلدهم،\nوالصحابة همّ كمان قرروا الرجوع للمدينة، وهمّ راجعين بقى \nفي مجموعة استأذنوا القائد إنهم محتاجين يرتاحوا، ويُوقدوا نار عشان يتدفوا، \nفوافق قائد السرية وجعل القائد عليهم عبدالله بن حذافة السهمي، فكان عبد الله عايز يهزر معاهم،\nفقالهم قوموا اقفزوا في النار،\nفقام مجموعة فعلا منهم وبداوا يستعدوا إنهم يقفزوا في النار\nفهنا عبد الله بن حذافة لما لقاهم أخدوا الموضوع بجد قالهم أنا كنت بهزر ،\nوهمّ سمعوا كلامه لأن طاعة قائد الجيش واجبة ومينفعش حد يخالف أمره، ففكروا إن الأمر ده كمان يدخل في طاعة القائد،\nفلما رجعوا للمدينة وأخبروا رسول الله ﷺ باللي حصل، قال لهم:\n\"من أمرَكم بمعصيةِ اللَّهِ فلا تطيعوهُ\"\nودي قاعدة لكل مسلم، أي حد يأمرنا بمعصية الله لا نطيعه، وهنا المعصية كانت إهلاك النفس وأذيتها،\nهمّ لما يرموا نفسهم في النار إيه إللي هيحصل لهم؟\nأقل شيء لو لم يموتوا هيحصل لهم حروق شديدة\nورسول الله ﷺ قال: لا ضرر ولا ضِرار، أي حاجة هتضرنا منعملهاش، \nفأي حد يأمرنا بمعصية الله لا طاعة له حتى لو كان مين\nاستمر رسول الله ﷺ في إرسال السرايا لنشر التوحيد في الجزيرة العربية وهدم الأصنام، \nففي شهر ربيع الأول برده جهّز سرية من مائة وخمسين واحد من الصحابة وخلّى على بن أبي طالب رضي الله عنه قائد للسرية دي،\nكانت مهمة السريّة هدم صنم الفُلس إللي كانت تعبده قبيلة طَيْء، ودعوتهم للإسلام،\nلما وصلت السرية لمكان الصنم هدموه وخرّبوه وأغارت السرية على أحياء من العرب،\nومن إللي أغاروا عليهم كانت قبيلة طيء، \nو القبيلة دي هي قبيلة حاتم الطائي وهو شاعر جاهلي وكان أمير وزعيم قبيلة طيء قبل ما يموت وكان مشهور بكرمه لدرجة إنه بقى مضرب المثل في الكرم،\nوكان حَسن الخُلق ويساعد المحتاجين، ولكنه مات على الكفر،\nوبقى ابنه عَدِيّ هو أمير القبيلة، يعني هو الزعيم المسؤول عن القبيلة دي، وكان عدي بن حاتم على النصرانية، وكان قومه بيعبدوا الأصنام،\nولما سمع عدي بن حاتم الطائي عن خروج رسول الله ﷺ وعرف الدين إللي بيدعو له رسول الله ﷺ ،كرهه عَدِيّ \nوكان رافض فكرة الدخول في الإسلام، \nوكان عارف إن رسول الله ﷺ بيرسل السرايا عشان يدعو الناس للإسلام، والدور كان هييجي عليه،\nفقال لغلام له كان بيرعى الإبل بتاعته: جهز لي من الجمال بتاعتي دي كم جمل كده سمين وحلو أخليهم قريبين مني،\nو أول ما تسمع إن جيش محمد وصل لأرضنا قولي على طول\nففي اليوم إللي جاء فيه علي رضي الله عنه وهجم على قبيلة طيء زي ما قلنا من شوية؛ الغلام راح لعدي بن حاتم وقاله إن خيل رسول الله ﷺ جاءت،\nفأخذ عدِي الجمال إللي كان مخليها معاه ومجهزها وأخذ زوجته وعياله وانطلق باتجاه للشام، إللي كانت تحت حكم الروم النصارى، وهو على دينهم فهيعيش معاهم،\nفمشي في الصحراء باتجاه الشام وساب أخته مع باقي القبيلة، إللي أسرتها خيل المسلمين مع باقي الأسرى من النساء والأطفال و هرب الرجال\nورجعت السرية للمدينة ومعاهم الأسرى، وعرف رسول الله ﷺ خبر فرار عدي بن حاتم للشام،\nو وُضِع النساء السبايا عند باب المسجد في مكان مخصص للسبايا، وكانت ابنة حاتم الطائي معهن، فمرّ بها رسول الله ﷺ  فقامت إليه وقالت:\nيا رسول الله، هلك الوالد وغاب الوافد فامنن عليّ مَنَّ الله عليك!\nفسألها رسول الله ﷺ: \n قال: \"مَنْ وَافِدُك؟\"\n فقالت: عَدِيّ بن حاتم.\nفقال لها: \"الهارب من الله ومن رسوله؟\nفسكتت وتركها رسول الله ﷺ ومشي، تاني يوم مَر عليها رسول الله ﷺ مرة تانية وقالت له نفس الكلام فرد عليها رسول الله ﷺ بنفس الرد، فسكتت وتركها رسول الله ﷺ ومشي،\nوجاء رسول الله ﷺ تالت يوم، لكنها يئست وفضلت قاعدة مكانها متكلمتش،\nفكان علي رضي الله عنه موجود فشاور لها إنها تقوم وتكلم رسول الله ﷺ، فقامت وقالت:\n\"يا رسول الله هَلَك الوالد وغاب الوافد فامنن عليّ مَنَّ الله عليك\"\nفقال رسول الله ﷺ: \n\"فإني قد فعلت، ولا تَعجلي بخروج حتى تجدي من قومك مَن يكون لكِ ثقة حتى يبلغك إلى بلادك ثم آذنيني\"\nيعني أنا هسيبك تمشي، لكن متستعجليش في الخروج لحد ما تلاقي حد ثقة يوصلك لبلدك وبعدها تعالي قوليلي،\nففضلت قاعدة في المدينة لحد ما جاء رَكْب من قُضاعة فقالت لهم إنها عايزة تروح لأخوها في الشام،\nفراحت لرسول الله ﷺ وقالت له:\n\"قد جاءني من قومي مَنْ لِي ثقَة وَبلاَغ\"\nيعني لقيت الثقة إللي هيوصلني للمكان إللي أنا عايزاه،\nفجهزها رسول الله ﷺ للسفر وأعطاها بعض المال وخرجت معهم لحد ما وصلت للشام،\nفي الوقت ده كان عدِي قاعد وسط أهله، فلقى امرأة متجهة ناحيته، فقال : ابنة حاتم\nفلما قربت منه فعلا لقاها أخته، فلما وصلت عنده قعدت تلومه بقى وقالت: القاطع الظالم، احتملتَ بأهلك وولدك وتركت بقية والدك\nيعني انت أخدت أهلك وعيالك وسيبت أختك، فقال لها عدي:\nيَا أُخَيَّة، لا تقولي إلا خيرًا، فوالله مالي من عُذر، قد صنعتُ ما ذكرتِ\nيعني معلش متزعليش أنا غلطان فعلا ومليش أي عذر،\nفأخته قعدت معاه في الشام، فسألها عدي عن رسول الله ﷺ وكانت امرأة عاقلة حازمة فقال:\nما تَرَين في أمر هذا الرجل؟ \nقالت:\nأرى والله أن تَلْحقَ به سريعًا، فإن يكن الرجل نبيًا فللسابقِ إليه فضلُه،\nوإن يكن ملكًا فلن تَذِلّ في عزّ اليمن، وأنت أنت\"\nيعني بتقوله رأيي إنك تروح وتتبعه، فلو كان نبي أي حد بيسابق بالإسلام بيكون له فضل، ولو كان ملك وانت اتبعته فانت أكيد مش هتبقى ذليل وهيبقى لك مكانة، وانت أصلا زعيم قومك،\nفقال: واللهِ إنَ هذا الرأيُ\nيعني هو ده الراي الصحيح، \nفخرج من الشام واتجه للمدينة ودخل المسجد وسلم على رسول الله ﷺ، فسأله رسول الله ﷺ:\nمن الرجل؟\nفقال: عدي بن حاتم\nفقام رسول الله ﷺ أخذ معاه عدي بن حاتم واتجهوا لبيته، وهم لسه ماشيين قابلت رسول الله ﷺ امرأة ضعيفة كبيرة فوقفته،\nفوقف معاها رسول الله ﷺ يكلمها ويشوفها محتاجة إيه، ووقف معاها وقت طويل وكل ده وعدي بن حاتم واقف معاه،\nفقال عدي في نفسه:\nوالله ما هذا بملك \nيعني محمد ﷺ مش ملك؛ لأن مش من عادة الملوك إنهم يقفوا مع عامة الناس كده ويسمعوهم ويشوفوا حاجتهم،\nلما المرأة خلصت مع رسول الله ﷺ كملوا الطريق لحد ما دخلوا بيت رسول الله ﷺ،\nفلما دخلوا البيت، رسول الله ﷺ أخذ وسادة من جلد محشية بالليف و ألقاها لحاتم وقاله يقعد عليها،\nفقال له عدي لأ انت إللي تقعد عليها، فقال له رسول الله ﷺ:\nبل أنت\nفجلس عليها عدي، وجلس رسول الله ﷺ على الأرض، و رأى رسول الله ﷺ في رقبة عدي سلسلة متعلق فيها صليب، فقال له:\n\"يا عديُّ اطرح عنْكَ هذا الوثَنَ\"\nيعني انزع الصليب إللي في رقبتك ده وارميه، وسمع عدي رسول الله ﷺ وهو بيقرأ:\n\"اتَّخَذُوا أَحْبَارَهُمْ وَرُهْبَانَهُمْ أَرْبَابًا مِنْ دُونِ اللَّهِ\"\nفقال عدي:\nإنَّا لسنا نعبدُهم ، يعني احنا مش بنعبدهم، فقال له رسول الله ﷺ : أليسَ يُحرمونَ ما أحلَّ اللهُ فتحرِّمونَه ، ويحلُّونَ ما حرَّمَ اللهُ فتحلُّونَه؟\nيعني هم بيحللوا ويحرموا على مزاجهم وانتم بتسمعوا كلامهم، صح؟\nفقال له عدي: بلى ، فقال رسول الله ﷺ : فتلك عبادتُهم\nلأن التحليل والتَّحريم مِن خَصائصِ الله عز وجل، وإللي يتبع حد في التحليل والتحريم يبقى كده اتخذه إله من دون الله والعياذ بالله\nبدأ رسول الله ﷺ يدعو حاتم للإسلام لكن بطريقة مختلفة،\nفسأله وقال له:\n\"إِيهٍ يَاعَدِيّ! ألم تكن رَكُوسِيًّا؟\" \nيعني بيقوله مش انت على الركوسية ياعدي، ودي طائفة من طوائف النصارى، فقال له عدي:\n بَلَى\nفقال له رسول الله ﷺ:\n\"أو لم تكن تسير في قومك بالمِرْبَاع!\" \nيعني مش انت كنت بتاخد من قومك ربع الغنائم، فقال له عدي: بَلَى\nفقال له رسول الله ﷺ:\nفإن ذلك لم يكن يَحلّ لك في دينك\nيعني إللي انت بتعمله ده حرام في دينك، فقال له عدي\nقال: قلت: أجل والله\nفهنا قال عدي فعرفتُ أنه نبي مُرسَل يَعْرِف ما نَجْهَل\nرسول الله ﷺ عارف الدين إللي بيتبعه عدي وكمان عارف أحكامه، \nوعدي عارف إن أخذه لربع الغنيمة حرام في دينه ومع ذلك كان بياخده، ماهو محدش من قومه عارف حاجة\nفكده بقى واضح جدا لعدي إن رسول الله ﷺ نبي مرسل من عند الله عنده علم مش أي حد يعرفه،\nوكمل رسول الله ﷺ حواره مع عدي وقال له:\nلَعلك يا عدي بن حاتم إنما يمنعك من الدخول في هذا الدين ما ترى من حاجتهم، فوالله لَيُوشِكَنَّ المالُ يفيض فيهم حتى لا يوجد مَنْ يأخذه، \nولعله إنما يمنعك ما ترى من كَثرة عدوِّهم وقلة عَدَدِهم، فوالله ليوشكن يُسمع بالمرأة تخرج من القادسية على بعير حتى تزور هذا البيت لا تخاف، \nولعلك إنما يمنعك من الدخول فيه أن المُلْك والسلطان في غيرهم، \nوايم الله ليوشكن أن يُسْمَع بالقصور البِيض من أرض بَابِل قد فُتِحَتْ عليهم\". \nيعني رسول الله ﷺ بيقول لعدي بن حاتم انت مش عايز تدخل في الإسلام ومتردد لأنك شايف أد إيه المسلمين فقراء  ومعندهمش المال الكافي،\nفوالله لييجي اليوم إللي المال هيفيض ويبقى كتير في إيد المسلمين لدرجة إنهم مش هيلاقوا حد ياخد منهم الصدقات،\nولعل إللي مخليك برده مش عايز تدخل الإسلام إنك شايف عدد المسلمين قليل وأعداؤهم عددهم أكتر منهم،\nفوالله هييجي اليوم إللي تسافر فيه المرأة من القادسية في العراق وتيجي تحج البيت وهي لا تخاف من أحد ومش محتاجة تدخل في جوار حد يحميها،\nولعلك مش عايز تدخل الإسلام عشان شايف الملك والسلطان في غير أيدي المسلمين فوالله هييجي اليوم إللي تُفتح فيه القصور البيضاء بتاعة كسرى في العراق وتبقى في إيد المسلمين\nطبعا عدي بن حاتم كان بيسمع كلام رسول الله ﷺ وهو مذهول\nإزاي يعني المرأة هتسافر من غير جوار، أمّال فين قطاع الطرق ساعتها،\nوإزاي المسلمين هينتصروا على كسرى أعظم ملك على وجه الأرض ساعتها وياخدوا قصوره\nودخل عدي في الإسلام وبعد الموقف ده بحوالي ست سنين  المسلمين فتحوا بلاد فارس والروم وأسقطوا أعظم إمبراطوريتين على وجه الأرض ساعتها،\nوقال حاتم لما كان بيحكي قصة إسلامه إللي قلناها دي:\nقد مضت اثنتان وبقيت واحدة: لَيَفِيضَنَّ المالُ حتى لا يُوجد من يأخذه.\nيعني هو شاف حاجتين من التلاتة اتحققوا من إللي رسول الله ﷺ قال عليهم: فتوح فارس والروم وانتصار المسلمين عليهم، وشاف المرأة تسير من العراق لبيت الله الحرام من غير ما تكون في جِوار أحد،\nأما الثالثة إللي مشفهاش حاتم كانت استفاضة المال ودي حصلت في عهد الخليفة عمر بن العزيز واتكلمنا عنها واحنا بنتكلم عن علامات الساعة لو تفتكروا\n☆ملحوظة:\nطبعا يا جماعة قصة إسلام حاتم الطائي دي محصلتس في يوم ولّا اتنين، ده الموضوع أخد له فترة،\nيعني على ما أخته استنت حد تثق فيه وتسافر معاه،\nوبعدين سفرها للشام إللي لوحده بياخدله حوالي شهر رايح جاي\nبس أنا قلت القصة كلها هما على بعضها عشان مننساش الأحداث بتاعتها\nكده بقى واضح إن الدولة الإسلامية بقت قوية جدا، وكل شوية عمالة بتكبر، وشوفنا إزاي اتحولت من حركة مُضطهدة في مكة إلى دُوَيلة صغيرة في المدينة، ثم إلى دولة عظمى تأخذ مساحة ضخمة في الجزيرة العربية بكاملها،\nوطبعا ده أدى لإيه\nأدى إلى إن الدولة الرومانية تاخد قرار بإنهاء التواجد الإسلامي في شبه الجزيرة العربية\nإيه إللي حصل، وإزاي رسول الله ﷺ هيتعامل مع الموضوع ده؟\nده إللي هنعرفه الجزء الجاي إن شاء الله"}, {"n": 216, "l": "الجزء 190 | احداث السنه التاسعه من الهجرة | اسباب غزوة تبوك", "u": "", "t": "#قصص_الأنبياء(٢)\n#السيرة_النبوية\n#الحلقة_مائة_وتسعون\n#أحداث_السنة_التاسعة_من_الهجرة\n#أسباب_غزوة_تبوك\nوقفنا المرة إللي فاتت عند الدولة الرومانية إللي قررت إنها تقضي على الدولة الإسلامية في الجزيرة العربية،\nإيه بقى إللي حصل وخلاهم ياخدوا القرار ده\nهو بصفة عامة مادام في حق يبقى لازم يكون في باطل، ودي سنة كونية إلى قيام الساعة، \nيعني هيفضل في صراع بين أهل الحق وأهل الباطل لحد يوم القيامة،\nوأهل الباطل لهم مصالح عايزين يحافظوا عليها ومش بيهمهم غير مصلحتهم حتى لو على حساب المستضعفين،\nأهل الحق مختلفين، ده من أوائل الحاجات إللي بيعملوها إنهم بيدافعوا عن حقوق المستضعفين،\nفبالتالي المستضعفين هيبدأوا يتّبعوا أهل الحق\nوكده أهل الباطل هيبقوا في موضع ضعف ومصالحهم هتضيع\nوهو ده إللي حاصل دلوقتي مع الدولة الرومانية بقيادة هرقل زعيم الروم\nبعد فتح مكة وانتصار المسلمين في حنين؛ في قبائل عربية كثيرة في الجزيرة العربية خضعت للمسلمين، ومن أشهر القبائل دي قبيلة هوازن، \nوبكده الجزيرة العربية بقت أشبه بدولة إسلامية، لها وضعها وكيانها وهيبتها\nوده أدى إلى لفت أنظار الدولة الرومانية العظمى إللي موجودة في شمال الجزيرة العربية في منطقة الشام وما فوقها، \nفخلونا كده نشوف الأسباب إللي خلت الدولة الرومانية عايزة تقضي على الوجود الإسلامي في الجزيرة العربية :\n◇أولا:\nالدولة الرومانية شايفة إن الدولة الإسلامية قوتها بتكبر بشكل لافت للنظر، \nفبعد ما كانت حركة مضطهدة في مكة بقت دلوقتي دولة عُظمى تحكم مساحة ضخمة في الجزيرة العربية،\nوكان من ضمن حكم المسلمين اليمن وعُمان والبحرين،\nوبالوضع ده الدولة الرومانية هتبقى محصورة في النص بين الدولة الفارسية من ناحية الشرق، والدولة الإسلامية من ناحية الجنوب، \nيعني أعداءها محاصرينها من ناحيتين، وده كده خطر على الدولة الرومانية، فلازم حل\n◇ثانيا:\nهرقل زعيم الدولة الرومانية عارف إن الدولة الإسلامية بتتبع نبي، وعندهم دين صحيح مفيهوش أي تحريف،\nولو الدين ده اتساب كده فهيوصل حكم الإسلام لما تحت \nأقدام هرقل نفسه، \nزي ما هو قال في حواره مع أبي سفيان لو تفتكروا،\nفهو كان عارف إن دين الإسلام فيه ذاتية تقدر تخلي العرب أقوياء، \nوتخلي كل إللي يتبع الدين ده قوي للدرجة إللي تخليه يقدر يبتلع قوى ضخمة عالميا زي الدولة الرومانية أو الدولة الفارسية، فكان لازم يوقفوا امتداد الإسلام بأي طريقة\n☆والكلام ده بيفسر لنا الحرب المستمرة على أي حاجة تنتمي للإسلام؛ وخصوصا من الدول الكبرى لأنهم عارفين قوة وصدق الإسلام و سِعة انتشاره،\nوإنه حتى لو ابتدى بحاجة صغيرة هيكبر بعدين، فبيحاربوه من البداية وبيشغلوا المسلمين بالشبهات عشان ميبقوش فاضيين لبناء دولة إسلامية زي ما رسول الله ﷺ بناها\n◇ثالثا:\nفي حدود بين الجزيرة العربية وبين مصر والشام، وكانت مصر والشام ساعتها مليانة بالخيرات، وفي الوقت ده كانت مصر والشام تابعين للدولة الرومانية،\nولو تُرك الإسلام فمش بعيد إن مصر والشام يتحولوا ويبقوا تابعين لدولة الإسلام،\nوده كده هيبقى خسارة كبيرة جدا للدولة الرومانية\n◇رابعا:\nمنطقة الشام مليانة بأتباع الدولة الرومانية وخاصة من نصارى الشام،\n ولو تركوهم للمسلمين فمش بعيد أبداً إنهم يُسلموا، ده هرق نفسه كان بيفكر في الدخول في الإسلام ولكنه خاف على ملكه،\nفلو دخل نصارى الشام في الإسلام هتبقى خسارة كبيرة للدولة الرومانية\n ◇خامسا:\n ذكريات مؤتة\nمؤتة معدّاش عليها غير سنة تقريبا، واحنا شوفنا المسلمين عملوا إيه في الرومان وفي العرب المُوَالين لهم،\nفكان لازم يثأروا عشان يرجعوا هيبتهم تاني\n◇سادسا:\n من طبيعة أهل الأديان الأخرى إنهم مش بيرضوا عن دين الإسلام أبدا \nوربنا نفسه قالنا في القرآن:\n\"وَلَنْ تَرْضَى عَنْكَ الْيَهُودُ وَلا النَّصَارَى حَتَّى تَتَّبِعَ مِلَّتَهُمْ\"\nفاليهود والنصارى مش هيرتاحوا غير لما المسلم مش بس يترك دينه، لأ، ده يتبعهم كمان،\nفبعد ما يتبين لهم الحق الموجود في الإسلام بيكونوا على أمرين: إما إنهم يكيدوا للإسلام، وإما إنهم يدخلوا فيه،\nفبدون أي مصالح أو أسباب لن ترضى الدولة الرومانية عن الدولة الإسلامية إلا في حالة واحدة بس:\nوهي لما الدولة الإسلامية تترك دينها وتتحول إلى النصرانية،\nوطبعا لأن ده مش هيحصل فاحتمال القتال هيفضل موجود ومش هيتوقف أبدا بين الطرفين، وده إللي ربنا قالهولنا في القرآن:\n\" وَلا يَزَالُونَ يُقَاتِلُونَكُمْ حَتَّى يَرُدُّوكُمْ عَنْ دِينِكُمْ إِنِ اسْتَطَاعُوا\"\n◇النقطة السابعة والأخيرة:\nغرور القوة، بمعنى، إن القوي المتكبر لا يقبل بوجود قوي آخر معاه، \nيعني هرقل عمره ما هيرضى بوجود عظيم إلى جواره، و زي ما كان بيقاتل كسرى عظيم الفرس قبل كده، فأكيد هيقاتل عظيم المسلمين رسول الله ﷺ\nفكل الأسباب دي وغيرها أدت إلى اجتماع الرومان واتحادهم مع قبائل العرب النصرانية زي الغساسنة عشان يُبيدوا المسلمين\nطبعا رسول الله ﷺ كان متوقع وعارف إن الدولة الرومانية مش هتسكت وهتجهز جيش للقضاء على المسلمين،\nوكان رسول الله ﷺ معرّف الصحابة بإحتمالية مواجهة الروم والغساسنة في معركة كبيرة زي معركة مؤتة أو أشد،\nوكان رسول الله ﷺ حاطط عيون في منطقة شمال الجزيرة العربية عشان تراقب الأوضاع،\nولو العيون دي شافت أي تحرك أو تجمع للرومان على طول يروحوا يبلغوا رسول الله ﷺ في المدينة،\nوأول ما بدأت قوات الرومان و العرب النصارى يتجمعوا؛ وصل الخبر لرسول الله ﷺ وبدأ يفكر هيعمل إيه\n☆ملحوظة:\nخلال الفترة ما بين معرفة رسول الله ﷺ لتجمع الرومان وقبل ما ياخد القرار هيعمل إيه مع الرومان حصلت حادثتين،\nالأولى: هي إِيلَاء رسول الله ﷺ من زوجاته.\nوالثانية: هي تخيِير زوجات رسول الله ﷺ بين البقاء معه أو إنه يطلقهن.\nالحادثتين دول محتاجين شرح وتفصيل، عشان كده هنخليهم لوحدهم نحكيهم مع بعض واحنا بنتكلم عن الأحداث الداخلية في المدينة، بعد ما نخلص الكلام عن غزوة تبوك،\nفدلوقتي هنركز بس على غزوة تبوك والأحداث بتاعتها عشان متحصلش لخبطة والأحداث تدخل في بعض\nبعد ما رسول الله ﷺ عرف بتجهيز جيش الرومان بدأ يفكر هيعمل إيه،\nرسول الله ﷺ كان عنده اختيار من اثنين: \n◇الأول:\nإما إنه يستنى جيش الرومان في المدينة لحد ما ييجوا ويحصل القتال في المدينة.\n◇الثاني:\n إن رسول الله ﷺ يذهب إليهم في شمال الجزيرة العربية ويحصل القتال هناك.\nالأسهل هنا إن رسول الله ﷺ والمسلمين ينتظروا الرومان في المدينة؛ لأن المسافة بعيدة جدا عن المدينة، وهيمشوا في الصحراء مئات الكيلو مترات،\nوده مش بس سفر مُتعب، ده محتاجين طعام وشراب يكفيهم المسافة دي كلها رايح جاي، فمحتاجين أموال وزاد كتير جدا،\nده غير كده في احتمال إن الجيش الروماني يهلك في الصحراء وهو في طريقه للمدينة ودي مصلحة للمسلمين\nلأن الجنود في الجيش الروماني طول عمرهم عايشين في أماكن خضراء في أوروبا والشام وفي غيرها من المناطق الباردة،\nومجربوش السفر في داخل الصحراء لمسافات طويلة قبل كده\nلكن مع ذلك رسول الله ﷺ قرر إنه يخرج بجيش المسلمين من المدينة ويروح هو لقتال جيش الرومان في المنطقة إللي تجمع فيها جيش الرومان،\nطب ليه بقى رسول الله ﷺ أخد القرار ده\n◇أولا:\nعشان هو ياخد عنصر المُبادأة، بمعنى إن هو إللي يختار بنفسه مكان وزمان الحرب، بدل ما الحرب تُفرض عليه.\n◇ثانيا:\nعشان يكون عنده خط دفاع تاني، يعني لو حصل الغزو في المدينة في عُقر دار المسلمين وسقطت المدينة وانهزم جيش المسلمين، هيروح فين بعد كده\nولو سقطت المدينة سقط الإسلام في الجزيرة العربية، واحنا عارفين إن معظم العرب لم يدخلوا الإسلام إلا من وقت قريب، وإسلامهم لسه مش قوي أصلا،\nورسول الله ﷺ لازم يحط احتمال الهزيمة عشان لو أي حاجة حصلت يبقى واخد احتياطاته، مش معنى إنه نبي يبقى احتمال الهزيمة بعيد،\nلأ، ومننساش إللي حصل في غزوة أُحد وحُنين\n◇ثالثاً: \nعشان يُظهر عزة الإسلام وقوته، وعدم جبنه أو رهبته من القتال\nو الثبات والإقدام ده له أثر كبير جدا على نفوس الأعداء، سواء كان الأعداء من الرومان أو الفرس أو غيرهم،\nالأعداء لما يلاقوا الجيوش الإسلامية مش خايفة من الموت، وجايين لبلادهم عشان يحاربوهم في ظروف صعبة؛ \nفده هيخلي في رهبة في قلوبهم من المسلمين ومش بعيد يخافوا وينسحبوا أصلا من غير قتال\n◇السبب الرابع والأخير:\nبعد غزوة مؤتة دخل الإسلام في بعض قبائل شمال الجزيرة العربية، وبكده رسول الله ﷺ بقى له شعب في شمال الجزيرة العربية،\nودول أول ناس ممكن يتعرضوا للهجوم من الجيش الروماني،\nورسول الله ﷺ  كزعيم مسئول لا يترك شعبه هكذا بدون حماية، \nمش بيعمل زي ما كثير من الزعماء بيعملوا، إنهم بيأمّنوا حدود العاصمة فقط، ويتركوا الشعب يعاني من ويلات العدو، وبعدين يهربوا بعد كده من العاصمة إذا اتحاصرت\nفرسول الله ﷺ أخد القرار بالخروج بنفسه لقتال أعظم و أقوى قوة في العالم ساعتها؛ ليحفظ دماء شعبه، حتى لو كانوا فقراء بسطاء بيعيشوا في أطراف الصحراء\nكده فهمنا وضع الدولة الإسلامية من وجهة نظر الرومان وفهمنا قرار رسول الله ﷺ بالخروج للقتال،\nنيجي بقى لتنفيذ القرار ده،\nالمفروض إن رسول الله ﷺ هيجهز جيش يواجه بيه أربعين ألف مقاتل من الرومان و من المتحالفين معاهم من نصارى العرب، وعشان الجيش يخرج  فاحنا محتاجين أموال وطعام،\nفي الوقت ده بقى كان في أزمة اقتصادية شديدة في المدينة\nكان بقالهم فترة مجنوش المحصول،\nيعني الزرع مكنش طلع بقاله فترة فمفيش محصول، \nوفي الوقت إللي المفروض الجيش يخرج فيه كان هو ده موسم الحصاد،\nولو المسلمين استنوا بس شوية هيجنوا الثمار والأزمة الاقتصادية تتحل،\nلكن في نفس الوقت لو استنوا، في احتمال إن جيوش الرومان تهجم على الدولة الإسلامية فمش هينفع يستنوا\nودي كانت أول مشكلة تواجه رسول الله ﷺ والصحابة\nالمشكلة التانية كانت الحر الشديد،\nيعني وقت خروج الجيش كان في آخر شهور الصيف، وتخيلوا بقى وضع جيش يمشي في صحراء قاحلة في الجو الشديد الحرارة ده في الجزيرة العربية\nوالناس إللي راحت  للعمرة أو الحج في داخل المدينة في الحر هيعرفوا صعوبة الحركة في الجو ده، مع إن الأمور تعتبر متيسرة إلى حد كبير في زماننا دلوقتي،\nومع ذلك الحر لا يُحتمل، فما بالكم باختراق الصحراء على الجمال أو سيراً على الأقدام،\nوالمسافة من المدينة إلى تبوك إللي هيخيم فيها رسول الله ﷺ بعدين هي سبعمائة كيلو متر، \nوده بالقياس في عصرنا الحديث لو هنمشي في خط مستقيم، \nأما طُرق الصحراء فأكيد إنها كانت أطول من كده، وكانت طرق مُلتَفّة وملتوية وصعبة، ومفيش مرواح ولا تكييفات ولا مظلات، \nهيمشوا منهم للشمس كده في الحر مسافة أسبوعين على الأقل\nوضيفوا بقى لكل ده إن المسلمين هيواجهوا عدو قوي جدا العرب عمرهم ما كانوا يتخيلوا أبدا مواجهة الجيش ده،\nدولة الرومان دولة ضخمة ولها تاريخ طويل في الحروب وانتصرت على تاني أقوى دولة في العالم دولة فارس،\nفالجيش الروماني ده لا يُستهان بيه أبدا،\nفكده اجتمع على المسلمين ثلاثة ابتلاءات، ابتلاء نقص المال وابتلاء الحر وابتلاء قوة العدو،\nفكانت الغزوة دي غزوة عَسيرة، ومش احنا إللي سميناها كده، ده ربنا العالم بكل شيء وعالم أد إيه الظروف كانت صعبة على المسلمين هو إللي وصفها بالعُسْرة، قال:\n\" فِي سَاعَةِ الْعُسْرَةِ\"\nفي الظروف الصعبة دي أُمر المسلمون بالخروج للجهاد في سبيل الله، وكان امتحان صعب جدا على المسلمين\nوالسؤال إللي بيطلع لنا هنا هو : ليه ربنا بيعسّر  الأمور على رسول الله ﷺ والصحابة كده ويخليهم يعدوا على الامتحان الصعب ده\nشوفوا،\nالدولة الإسلامية في الوقت ده وصلت لدرجة من القوة محدش كان يتخيلها، \nيعني بقى لها اتباع كتير جدا، وبقت دولة ذات هيبة وسيادة وتمكين في الجزيرة العربية خلت العرب بيسارعوا للدخول تحت حكمها،\nوكان في ناس منهم تظاهروا بالإسلام وهم يُبطنون الكفر، أو الكراهية للدولة الإسلامية،\nوده إللي اسمه النفاق\nوالمنافقين مش بيظهروا في الدولة الضعيفة إلا نادرا، لكن بيظهروا كتير كل ما زادت قوة الإسلام والمسلمين وزاد التمكين لهم،\nفكل ما زاد التمكين للمسلمين ربنا بيصعّب الاختبار على المؤمنين، ليييه؟\nلتمييز المؤمن من المنافق، ولكَشْف المنافقين أمام أهل الإيمان\nوكل ما كان الامتحان صعب كان الناجح فيه أصدق \nو دي سُنّة ربنا في الكون، زي ما في امتحان يميّز الطالب إللي ذاكر من الطالب إللي مذاكرش،\nفكذلك في ابتلاء عشان عشان يظهر المؤمن الثابت على الإيمان من المنافق إللي أي ابتلاء يحصل له يسقط فيه،\nوربنا بيقول:\n\"أَحَسِبَ النَّاسُ أَنْ يُتْرَكُوا أَنْ يَقُولُوا آمَنَّا وَهُمْ لا يُفْتَنُونَ*\nوَلَقَدْ فَتَنَّا الَّذِينَ مِن قَبْلِهِمْ ۖ فَلَيَعْلَمَنَّ اللَّهُ الَّذِينَ《 صَدَقُوا》 وَلَيَعْلَمَنَّ 《الْكَاذِبِينَ》\"\nفاللي عايز يعرف إيمانه صادق ولّا لأ يشوف نفسه في الوقت البلاء عامل إزاي\nوعلى فكرة يا جماعة رسول الله ﷺ كان ممكن يعرف المنافقين عن طريق الوحي من غير اختبارات ولا أي حاجة\nلكن لازم المسلمين يتعلموا الطريقة إللي يقدروا بيها اكتشاف المنافقين في داخل الصف المسلم؛ لأن بعد وفاة رسول الله ﷺ  مش هيبقى في وحي\n☆طب وإيه المشكلة يعني لما يكون في منافقين في الصف المسلم\n الموضوع ده عايز له شرح من خلال المواقف إللي المنافقين عملوها، وده إللي هنعرفه الجزء الجاي إن شاء الله"}]);
